  function sfxBigLaser() { const n = Date.now(); if (n - _sfxTurretAt < 90) return; _sfxTurretAt = n; _tone(700, 0.24, 'sawtooth', 0.075, 80); _tone(300, 0.24, 'square', 0.04, 60); } // เลเซอร์ใหญ่ (ป้อม)
