        const _fxA = 1 - _fxAge / 1000; // จางเชิงเส้นจนหมดพอดีตอน tick ถัดไป
        if (_priestFx.skill === 'energy' && _hasRobot && _rpB) _headIco(_rpB.x, _rpB.y, _fxIco, _fxA, 24);
        else _headIco(_pp.x, _pp.y, _fxIco, _fxA, 26);
