    const _tp = smoothed('priest', _pp.x - 16, _pp.y + 12);
    const s = toScreen(_tp.x, _tp.y);
    const _moving = Math.abs(_tp.tx - _tp.sx) + Math.abs(_tp.ty - _tp.sy) > 0.8; // กำลังไล่ตาม = เดิน
