      const fi = Math.floor(Date.now() / 140) % frames, sz = 60 * scale; // ×2 (30→60 · 2026-07-14 ผู้ใช้ขอใหญ่ขึ้นเท่าตัว)
      ctx.save(); ctx.imageSmoothingEnabled = false; ctx.translate(s.x, s.y);
