  function _makeHelpToggler(boxId, rows, rowClass) {
    return function() {
      const box = document.getElementById(boxId);
      if (!box) return;
      if (box.style.display !== 'none') { box.style.display = 'none'; return; }
      box.innerHTML = rows.map(s => `
        <div class="${rowClass}-row">
          <span class="${rowClass}-icon">${s.icon}</span>
          <div class="${rowClass}-text">
            <div class="${rowClass}-name">${T(s.name)}</div>
            <div class="${rowClass}-desc">${T(s.desc).replace(/\n/g,'<br>')}</div>
          </div>
        </div>`).join('');
      box.style.display = 'block';
    };
  }

