  // ── Leaderboard ───────────────────────────────────────────
  let rankCurrentTab = 'lv'; // default = อันดับผู้เล่น (Lv/EXP) · MVP ย้ายไปแท็บสอง
  let rankCC = 'ALL';        // 🌐 filter รายประเทศ (ISO2 · 'ALL' = ทุกประเทศ) — ใช้ร่วมทุกแท็บที่กรองได้

  function rankTab(tab) {
    rankCurrentTab = tab;
    document.querySelectorAll('.rank-tab').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
    renderRank();
  }
  let _rankCCs = []; // เก็บรายชื่อประเทศล่าสุด (ให้ popup ตัวเลือกใช้ · เลี่ยงยิง query ซ้ำ)
  function _rankSetCC(cc) { rankCC = cc; _rankCCClose(); renderRank(); }
  // ปุ่มเดียวโชว์ประเทศที่กรองอยู่ — กดเปิด popup เลือก (เดิมเรียงธงยาวเป็นแถว = รก)
  function _rankCCBar(ccs) {
    if (!ccs || !ccs.length) { _rankCCs = []; return ''; }
    _rankCCs = ccs;
    const cur = rankCC === 'ALL' ? '🌐 ' + T('ทุกประเทศ') : _ccFlag(rankCC) + rankCC;
    return `<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px">
      <span style="color:#94a3b8;font-size:11px">${T('กรองประเทศ')}</span>
      <button onclick="xhrpg._rankCCOpen()" style="display:inline-flex;align-items:center;gap:5px;border:1px solid #c4b5fd;background:#f5f3ff;color:#6d28d9;cursor:pointer;border-radius:8px;padding:4px 10px;font-size:12px;font-weight:700">${cur} <span style="font-size:9px;opacity:.7">▼</span></button>
    </div>`;
  }
  function _rankCCClose() { const el = document.getElementById('rank-cc-ov'); if (el) el.remove(); }
  function _rankCCOpen() {
    _rankCCClose();
    // ปุ่มขนาดเท่ากันทุกอัน (grid 2 คอลัมน์) — ธง+รหัสชิดซ้าย · จำนวนคนชิดขวา เรียงตรงกันทุกแถว
    const item = (code, flag, cc, cnt) => {
      const on = rankCC === code;
      return `<button onclick="xhrpg._rankSetCC('${code}')" style="display:flex;align-items:center;gap:6px;width:100%;box-sizing:border-box;border:1px solid ${on?'#7c3aed':'#e2e8f0'};background:${on?'#7c3aed':'#fff'};color:${on?'#fff':'#334155'};cursor:pointer;border-radius:9px;padding:8px 11px;font-size:12.5px;font-weight:700">
        <span style="flex:none;display:inline-flex;align-items:center">${flag}</span>
        <span style="flex:1;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${cc}</span>
        ${cnt != null ? `<span style="flex:none;opacity:.65;font-weight:400;font-size:11px">${cnt}</span>` : ''}</button>`;
    };
    const grid = item('ALL', '🌐', T('ทุกประเทศ'), null) + _rankCCs.map(c => item(c.cc, _ccFlag(c.cc), c.cc, c.n)).join('');
    const el = document.createElement('div');
    el.id = 'rank-cc-ov';
    el.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.6);z-index:10002;display:flex;align-items:center;justify-content:center;padding:20px';
    el.innerHTML = `<div style="background:#fff;border-radius:16px;max-width:360px;width:100%;max-height:74vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 50px rgba(0,0,0,.4)">
      <div style="padding:12px 16px 10px;display:flex;justify-content:space-between;align-items:center;flex:none;border-bottom:1px solid #f1f5f9">
        <b style="font-size:14px;color:#1e293b">🌐 ${T('เลือกประเทศ')}</b>
        <button onclick="xhrpg._rankCCClose()" style="background:none;border:none;color:#94a3b8;font-size:18px;cursor:pointer">✕</button>
      </div>
      <div style="padding:12px 14px 16px;overflow:auto;display:grid;grid-template-columns:1fr 1fr;gap:8px">${grid}</div>
    </div>`;
    el.addEventListener('click', e => { if (e.target === el) _rankCCClose(); });
    document.body.appendChild(el);
  }

  // ── อันดับผู้เล่น: มินิสไปรต์ตัวละคร (crop เฟรม 0 · trim bbox · upscale) → dataURL cache ต่อชีท ──
  const _lbAvCache = {};
  function _lbAvatarURL(img, rows) {
    if (!img || !img.naturalWidth) return null;
    rows = rows || 1;
    const key = (img.src || '') + '|' + rows;
    if (key in _lbAvCache) return _lbAvCache[key];
    try {
      const fh = Math.round(img.naturalHeight / rows), fw = fh; // เฟรมจัตุรัส
      const tmp = document.createElement('canvas'); tmp.width = fw; tmp.height = fh;
      const tc = tmp.getContext('2d'); tc.imageSmoothingEnabled = false;
      tc.drawImage(img, 0, 0, fw, fh, 0, 0, fw, fh); // เฟรม 0 (มุมซ้ายบน = หันหน้า/idle)
      const data = tc.getImageData(0, 0, fw, fh).data;
      let minx = fw, miny = fh, maxx = 0, maxy = 0, any = false;
      for (let y = 0; y < fh; y++) for (let x = 0; x < fw; x++) {
        if (data[(y * fw + x) * 4 + 3] > 30) { any = true; if (x < minx) minx = x; if (x > maxx) maxx = x; if (y < miny) miny = y; if (y > maxy) maxy = y; }
      }
      if (!any) { _lbAvCache[key] = null; return null; }
      const bw = maxx - minx + 1, bh = maxy - miny + 1;
      const S = Math.max(1, Math.floor(96 / Math.max(bw, bh)));
      const out = document.createElement('canvas'); out.width = bw * S; out.height = bh * S;
      const oc = out.getContext('2d'); oc.imageSmoothingEnabled = false;
      oc.drawImage(img, minx, miny, bw, bh, 0, 0, bw * S, bh * S);
      const url = out.toDataURL('image/png');
      _lbAvCache[key] = url; return url;
    } catch (e) { _lbAvCache[key] = null; return null; } // tainted/โหลดไม่ทัน → fallback emoji
  }
  function _lbToon(url, cap, kind, emoji, empty) { // kind: 'prem' | 'mvp' | ''
    const star = kind === 'mvp' ? '<span class="rank-star">⭐</span>' : (kind === 'prem' ? '<span class="rank-star">✨</span>' : '');
    let inner, ec = '';
    if (empty)     { inner = `<span class="rank-dash">—</span>`; ec = ' empty'; }
    else if (url)  { inner = `<img src="${url}" alt="">`; }
    else           { inner = `<span class="rank-emoji">${emoji}</span>`; }
    return `<div class="rank-toon ${kind}${ec}">${star}<div class="rank-frame">${inner}</div><div class="rank-cap">${cap}</div></div>`;
  }
  function _lbCast(r) {
    const heroU  = _lbAvatarURL(r.hero_skin  ? SUM['hs_' + r.hero_skin + '_idle'] : SUM['th_idle'], 4);
    const titanU = _lbAvatarURL(r.robot_skin ? SUM['skin_' + r.robot_skin + '_idle'] : SUM['robot_idle'], 1);
    const dogU   = _lbAvatarURL(r.pet_skin   ? SUM['pet_' + r.pet_skin + '_idle'] : SUM['dog_idle'], 1);
    let petU = null, petName = T('สัตว์เลี้ยง'); const _pm = r.pet_mid | 0;
    if (_pm > 0 && monMasters[_pm]) {
      const _mm = monMasters[_pm], _sk = MON_ANIM[_mm.lv | 0];
      if (_sk && SUM[_sk]) petU = _lbAvatarURL(SUM[_sk], (MON_GRID[_sk] || _MON_GRID_DEF).rows);
      petName = (r.pet_mvp ? '⭐' : '') + T(_mm.n || 'มอน') + ' Lv.' + (_mm.lv || 1); // ชื่อมอน + Lv (MVP มีดาว)
    }
    return `<div class="rank-cast">
      ${_lbToon(heroU,  _heroSkinName(r.hero_skin),  r.hero_skin  ? 'prem' : '', '🧑', false)}
      ${_lbToon(titanU, _robotSkinName(r.robot_skin), r.robot_skin ? 'prem' : '', '🤖', false)}
      ${_lbToon(dogU,   _petSkinName(r.pet_skin),    r.pet_skin   ? 'prem' : '', '🐶', false)}
      ${_lbToon(petU,   petName, r.pet_mvp ? 'mvp' : '', '👾', _pm === 0)}
    </div>`;
  }

  // 🌐 แปล "เวลาที่แล้ว" ของแถว MVP kill log ตอนแสดงเท่านั้น — server (xhrpg_leaderboard.php) ส่งสตริงไทยประกอบแล้ว ("26 นาทีที่แล้ว")
  function _mvpAgoT(s) {
    s = String(s || '');
    if (LANG() === 'th') return s; // โหมดไทย = ตรง server เป๊ะ
    if (s === 'เมื่อกี้') return T('เมื่อกี้');
    const m = s.match(/^(\d+) (นาที|ชม\.|วัน)ที่แล้ว$/u);
    if (!m) return s;
    return T(m[2] === 'นาที' ? '{a} นาทีที่แล้ว' : m[2] === 'ชม.' ? '{a} ชม.ที่แล้ว' : '{a} วันที่แล้ว', {a: m[1]});
  }
  // 🌐 แปลคำอธิบายของวิเศษในป้าย drop — dict ตรงก่อน · แถวเก่าตัวเลขต่างจาก def ปัจจุบัน (เช่น "+2m") จับ pattern แทน
  function _mvpDescT(d) {
    const t = T(d); if (t !== d) return t;
    let m;
    if ((m = d.match(/^ระยะยิง (.+?) \+(.+)$/u))) return T('ระยะ {a} +{b}', {a: T(m[1]), b: m[2]}); // ผ่าน dict — เดิม hardcode EN ผิดกับภาษาอื่น
    if ((m = d.match(/^ระยะ (.+?) \+(.+)$/u)))    return T('ระยะ {a} +{b}', {a: T(m[1]), b: m[2]}); // เช่น "ระยะ Premium Titan Beam +3m"
    if ((m = d.match(/^ความจุกระสุน \+(\d+)$/u))) return T('ความจุกระสุน +{a}', {a: m[1]});
    return d; // ไม่รู้จัก → คงเดิม
  }
  // 🌐 แปลป้าย drop ของ MVP kill log ตอนแสดงเท่านั้น — DB (xhrpg_mvp_kills.drop_item) เก็บไทยเสมอ · pattern ไม่ตรง = คืนเดิม ไม่พังแถวเก่า
  function _mvpDropT(s) {
    s = String(s || '');
    if (LANG() === 'th') return s; // โหมดไทย = ตรง DB เป๊ะ
    const t0 = T(s); if (t0 !== s) return t0; // คีย์ตรง dict (💎เพชรฟ้า +1 ฯลฯ)
    let m;
    // 🎁 กล่องการ์ด Lv.{lo}-{hi}
    if ((m = s.match(/^🎁 กล่องการ์ด Lv\.(\d+)-(\d+)$/u))) return '🎁 ' + T('กล่องการ์ด Lv.{a}-{b}', {a: m[1], b: m[2]});
    // 📦 กล่องโมดูล{ระดับ}
    if ((m = s.match(/^📦 กล่องโมดูล(.+)$/u))) return '📦 ' + T('กล่องโมดูล{a}', {a: T(m[1].trim())});
    // 🔧 {อาวุธ} {ช่อง} ({ระดับ}) — โมดูลดรอปตรง (ชื่ออาวุธมีวรรคได้ เช่น "ธนูไททัน (ARM)" → ยึดชุดชื่อระดับปิดท้าย)
    if ((m = s.match(/^🔧 (.+) (\S+) \((ทั่วไป|ซับซ้อน|หายาก|ขั้นสูง|ขั้นสูงพิเศษ|ขั้นตำนาน|ตำนานพิเศษ)\)$/u)))
      return '🔧 ' + T(m[1]) + ' ' + T(m[2]) + ' (' + T(m[3]) + ')';
    // 🔧 {อาวุธ}! {ช่อง} ({ระดับ}) [STAT] — แถวเก่า (ก่อนมี hist — ตัด "ดรอปโมดูล" จาก msg)
    if ((m = s.match(/^🔧 (.+?)! (\S+) \((ทั่วไป|ซับซ้อน|หายาก|ขั้นสูง|ขั้นสูงพิเศษ|ขั้นตำนาน|ตำนานพิเศษ)\) \[([A-Z]+)\]$/u)))
      return '🔧 ' + T(m[1]) + ' ' + T(m[2]) + ' (' + T(m[3]) + ') [' + m[4] + ']';
    // 🎴การ์ด {มอน}[ MVP][ (+v STAT)] — แถวเก่ามี "!" ท้ายชื่อ
    if ((m = s.match(/^🎴การ์ด (.+?)( MVP)?!?(\s*\(\+.*\))?$/u)))
      return '🎴' + T('การ์ด {a}', {a: T(m[1]) + (m[2] || '')}) + (m[3] || '');
    // 🥚ไข่ {มอน}[ MVP]
    if ((m = s.match(/^🥚ไข่ (.+?)( MVP)?$/u))) return '🥚' + T('ไข่ {a}', {a: T(m[1]) + (m[2] || '')});
    // ของวิเศษ MVP 6 หมวด (ชิ้นใหม่ · scanner ตัด prefix "⭐MVP✨ " แล้ว): "{หัว}! {icon} {ชื่อ} — {คำอธิบาย}"
    if ((m = s.match(/^(พบของล้ำค่า!|ได้อุปกรณ์!|ได้ HARDWARE!|ได้ของวิเศษ STAT!|ได้ชิ้นส่วนยานบิน!|ได้ชิ้นส่วนอาวุธ!) (\S+) (.+?) — (.+)$/u)))
      return T(m[1]) + ' ' + m[2] + ' ' + T(m[3]) + ' — ' + _mvpDescT(m[4]);
    // ชิ้นซ้ำ: "{icon} {ชื่อ} (ซ้ำ xN)" / อุปกรณ์ "{icon} {ชื่อ} ซ้ำ xN" (ไม่มีวงเล็บ)
    if ((m = s.match(/^(\S+) (.+?) (\()?ซ้ำ x(\d+)\)?$/u)))
      return m[1] + ' ' + T(m[2]) + ' ' + (m[3] ? '(' + T('ซ้ำ x{a}', {a: m[4]}) + ')' : T('ซ้ำ x{a}', {a: m[4]}));
    // มอนตี Titan ระหว่างสู้ MVP หลุดเข้า drop log: "{icon}[ 🤖] ตีไททัน -13⚡ (เหลือ 788)"
    if ((m = s.match(/^(.*?)ตีไททัน -(\d+)⚡ \(เหลือ (\d+)\)$/u)))
      return m[1] + T('ตีไททัน -{d}⚡ (เหลือ {e})', {d: m[2], e: m[3]});
    return s; // ไม่รู้จัก → ไทยตามเดิม (แถวเก่า/ฟอร์แมตอนาคต — ห้ามพัง)
  }

  // ══ 💬 แชท (รวมทั้งเกม + ส่วนตัว · endpoint xhrpg_chat.php · docs sql/add_chat.sql) ══════
  //    ⚠️ ข้อความผู้เล่นสร้างด้วย textContent เท่านั้น — ห้าม innerHTML (กัน XSS: ข้อความมาจากคนอื่นพิมพ์)
  const CHAT_EMOJI = ['😀','😂','🥹','😍','😎','🤔','😭','😱','🥳','😴','👍','👎','🙏','👏','💪','🤝',
                      '🔥','⚡','💥','✨','⭐','🎉','🎁','💰','💎','🎴','🥚','🐾','⚔️','🛡️','🏹','🗡️',
                      '🛸','⛪','💀','👾','🌿','❤️','💔','🆘','❓','❗','➡️','⬅️','🆙','🏆'];
  let _chatTab = 'g';        // 'g' = รวม · 'dm' = ส่วนตัว
  let _chatWith = null;      // uid คู่สนทนา (แท็บ dm · null = โชว์รายชื่อห้อง)
  let _chatWithName = '', _chatWithCC = ''; // 🏴 ธงคู่สนทนา — โชว์ที่หัวข้อห้อง DM
  let _chatN = 0, _chatDmN = 0; // badge จาก poll
  let _chatBusy = false;

  // icon แมพอย่างเดียว (ไม่เอาชื่อ — คำขอเจ้าของ) · title = ชื่อเต็มตามภาษา (hover ดูได้)
  const _chatMapIcon = mp => MAP_DEFS.find(x => x.id === (+mp || 1)) || null;
  const _chatTime = ts => { const d = new Date((+ts || 0) * 1000); return String(d.getHours()).padStart(2,'0') + ':' + String(d.getMinutes()).padStart(2,'0'); };

  // badge ข้างปุ่ม 💬 (เรียกทุก poll จาก updateHUD)
  function _chatBadgeUpd() {
    const el = document.getElementById('chat-badge'); if (!el) return;
    const n = _chatN + _chatDmN;
    if (n > 0 && openPanel !== 'chat') { el.style.display = 'block'; el.textContent = n > 99 ? '99+' : String(n); }
    else el.style.display = 'none';
  }
  function _chatPost(data, cb) {
    $.post(baseUrl + 'xhrpg_chat.php', Object.assign({ line_uid: player.line_uid, session_token: sessionToken || '', lang: LANG() }, data), cb, 'json')
      .fail(() => { _chatBusy = false; });
  }
  function chatEmojiToggle() {
    const box = document.getElementById('chat-emoji'); if (!box) return;
    const show = box.style.display === 'none';
    box.style.display = show ? 'block' : 'none';
    if (show && !box.dataset.built) {
      box.dataset.built = '1';
      CHAT_EMOJI.forEach(e => {
        const b = document.createElement('button');
        b.textContent = e;
        b.style.cssText = 'width:30px;height:30px;border:none;background:transparent;font-size:17px;cursor:pointer;border-radius:6px';
        b.onmouseenter = () => b.style.background = '#f1f5f9';
        b.onmouseleave = () => b.style.background = 'transparent';
        b.onclick = () => { const i = document.getElementById('chat-input'); i.value = (i.value + e).slice(0, 200); i.focus(); };
        box.appendChild(b);
      });
    }
  }
  // ── วาดรายการข้อความ (DOM ล้วน — textContent กัน XSS) ──
  function _chatDraw(msgs, me) {
    const box = document.getElementById('chat-msgs'); if (!box) return;
    box.textContent = '';
    if (!msgs.length) {
      const d = document.createElement('div');
      d.style.cssText = 'text-align:center;color:#94a3b8;font-size:11px;padding:16px 0';
      d.textContent = T('ยังไม่มีข้อความ — ทักทายกันได้เลย');
      box.appendChild(d); return;
    }
    msgs.forEach(m => {
      const mine = m.u === me;
      const row = document.createElement('div');
      row.style.cssText = `display:flex;flex-direction:column;align-items:${mine ? 'flex-end' : 'flex-start'};margin-bottom:5px`;
      // หัว: [ธง] ชื่อ · แมพ · เวลา
      const hd = document.createElement('div');
      hd.style.cssText = 'font-size:9.5px;color:#64748b;margin-bottom:1px;display:flex;gap:4px;align-items:center';
      const _fl = _flagEl(m.cc, 9); if (_fl) hd.appendChild(_fl); // 🏴 ธงชาติผู้พูด (ทั้งของเราและคนอื่น)
      if (!mine) {
        const nm = document.createElement('b');
        nm.textContent = m.n || '?';
        nm.style.cssText = 'color:#0f766e;cursor:pointer';
        nm.title = T('💌 แชทส่วนตัว');
        nm.onclick = () => chatOpenDm(m.u, m.n || '?', m.cc);
        hd.appendChild(nm);
      } else {
        const nm = document.createElement('b'); nm.textContent = T('ฉัน'); nm.style.color = '#16a34a'; hd.appendChild(nm);
      }
      // 🌿 icon สถานที่ (แชทรวมเท่านั้น · hover = ชื่อเต็ม) → Lv. → 🌟 Ragnalok Lv
      if (m.mp) { const _md = _chatMapIcon(m.mp);
        if (_md) { const mp = document.createElement('span'); mp.textContent = _md.emoji; mp.title = T(_md.name); hd.appendChild(mp); } }
      if (m.lv) { const lv = document.createElement('span'); lv.textContent = 'Lv.' + m.lv; lv.style.color = '#475569'; hd.appendChild(lv); }
      if (m.rg) { const rg = document.createElement('span'); rg.textContent = '🌟' + m.rg; rg.style.cssText = 'color:#b45309;font-weight:700'; rg.title = 'Ragnalok Lv.' + m.rg; hd.appendChild(rg); }
      const tm = document.createElement('span'); tm.textContent = _chatTime(m.ts); tm.style.color = '#cbd5e1'; hd.appendChild(tm);
      row.appendChild(hd);
      // ฟอง
      const bb = document.createElement('div');
      bb.textContent = m.m || ''; // ⚠️ textContent = ปลอดภัย ห้ามเปลี่ยนเป็น innerHTML
      bb.style.cssText = `max-width:82%;padding:5px 9px;border-radius:11px;font-size:12.5px;line-height:1.45;white-space:pre-wrap;word-break:break-word;`
        + (mine ? 'background:#16a34a;color:#fff;border-bottom-right-radius:3px' : 'background:#fff;color:#0f172a;border:1px solid #e2e8f0;border-bottom-left-radius:3px');
      row.appendChild(bb);
      box.appendChild(row);
    });
    box.scrollTop = box.scrollHeight;
  }
  // ── แท็บ ──
  function _chatTabs() {
    const el = document.getElementById('chat-tabs'); if (!el) return;
    el.textContent = '';
    // ⚠️ key 'แชทรวม' (ไม่ใช่ 'รวม' — คีย์นั้นแปลว่า Total ใช้ในตลาดอยู่แล้ว คนละความหมาย)
    [['g', '🌐 ' + T('แชทรวม'), _chatN], ['dm', '💌 ' + T('แชทส่วนตัว'), _chatDmN]].forEach(([k, label, n]) => {
      const b = document.createElement('button');
      b.style.cssText = `flex:1;padding:6px 0;border:none;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;position:relative;`
        + (_chatTab === k ? 'background:#0f766e;color:#fff' : 'background:#f1f5f9;color:#475569');
      b.textContent = label;
      if (n > 0 && _chatTab !== k) {
        const bd = document.createElement('span');
        bd.textContent = n > 99 ? '99+' : String(n);
        bd.style.cssText = 'position:absolute;top:2px;right:6px;background:#dc2626;color:#fff;font-size:8.5px;font-weight:800;border-radius:7px;padding:0 4px;min-width:13px';
        b.appendChild(bd);
      }
      b.onclick = () => { _chatTab = k; _chatWith = null; renderChat(); };
      el.appendChild(b);
    });
  }
  // ── รายชื่อห้อง DM ──
  function _chatDmList(dms) {
    const el = document.getElementById('chat-dmlist'); if (!el) return;
    el.textContent = '';
    if (!dms.length) {
      const d = document.createElement('div');
      d.style.cssText = 'text-align:center;color:#94a3b8;font-size:11px;padding:20px 8px;line-height:1.7';
      d.textContent = T('ยังไม่มีแชทส่วนตัว — กดที่ชื่อคนในแท็บ 🌐 รวม เพื่อเริ่มคุย');
      el.appendChild(d); return;
    }
    dms.forEach(d => {
      const row = document.createElement('div');
      row.style.cssText = 'display:flex;gap:7px;align-items:center;padding:7px 8px;border:1px solid #e2e8f0;border-radius:9px;margin-bottom:4px;cursor:pointer;background:#fff';
      row.onclick = () => chatOpenDm(d.uid, d.name, d.cc);
      const mid = document.createElement('div'); mid.style.cssText = 'flex:1;min-width:0';
      const nm = document.createElement('div');
      nm.style.cssText = 'font-size:12.5px;font-weight:700;color:#0f172a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;gap:4px;align-items:center';
      const _dfl = _flagEl(d.cc, 10); if (_dfl) nm.appendChild(_dfl); // 🏴 ธงคู่สนทนา
      const _dnm = document.createElement('span'); _dnm.textContent = d.name || '?'; nm.appendChild(_dnm);
      const ls = document.createElement('div'); ls.textContent = d.last || '';
      ls.style.cssText = 'font-size:10.5px;color:#64748b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis';
      mid.appendChild(nm); mid.appendChild(ls); row.appendChild(mid);
      const rt = document.createElement('div'); rt.style.cssText = 'flex:none;text-align:right';
      const tm = document.createElement('div'); tm.textContent = _chatTime(d.ts); tm.style.cssText = 'font-size:9px;color:#cbd5e1';
      rt.appendChild(tm);
      if (d.n > 0) {
        const bd = document.createElement('div'); bd.textContent = d.n > 99 ? '99+' : String(d.n);
        bd.style.cssText = 'background:#dc2626;color:#fff;font-size:9px;font-weight:800;border-radius:8px;padding:1px 5px;margin-top:2px;display:inline-block';
        rt.appendChild(bd);
      }
      row.appendChild(rt);
      el.appendChild(row);
    });
  }
  function chatOpenDm(uid, name, cc) {
    if (!uid || uid === player.line_uid) return;
    _chatTab = 'dm'; _chatWith = uid; _chatWithName = name || '?'; _chatWithCC = cc || '';
    if (openPanel !== 'chat') togglePanel('chat'); else renderChat();
  }
  // ── render หลัก (เรียกตอนเปิดแผง + สลับแท็บ + poll ตอนเปิดอยู่) ──
  function renderChat() {
    if (!player) return;
    _chatTabs();
    const room = document.getElementById('chat-room'), dl = document.getElementById('chat-dmlist');
    const ttl = document.getElementById('chat-title');
    const inDmList = _chatTab === 'dm' && !_chatWith;
    if (room) room.style.display = inDmList ? 'none' : 'block';
    if (dl) dl.style.display = inDmList ? 'block' : 'none';
    if (ttl) { // หัวข้อ: ห้อง DM → 💌 [ธง] ชื่อ (DOM ไม่ใช่ innerHTML — ชื่อมาจากผู้เล่น)
      ttl.textContent = '';
      if (_chatWith) {
        ttl.style.cssText = 'display:flex;gap:5px;align-items:center';
        const _t1 = document.createElement('span'); _t1.textContent = '💌'; ttl.appendChild(_t1);
        const _tf = _flagEl(_chatWithCC, 11); if (_tf) ttl.appendChild(_tf);
        const _t2 = document.createElement('span'); _t2.textContent = _chatWithName; ttl.appendChild(_t2);
      } else { ttl.style.cssText = ''; ttl.textContent = '💬 ' + T('แชท'); }
    }
    if (inDmList) { _chatPost({ action: 'dms' }, r => { if (r && r.ok) _chatDmList(r.dms || []); }); return; }
    _chatPost({ action: 'fetch', with: _chatWith || '' }, r => {
      if (!r || !r.ok) return;
      _chatDraw(r.msgs || [], r.me);
      if (_chatWith) _chatDmN = Math.max(0, _chatDmN - 1); else _chatN = 0; // อ่านแล้ว → ดับ badge ทันที (poll ยืนยันอีกที)
      _chatBadgeUpd(); _chatTabs();
    });
  }
  function chatSend() {
    if (_chatBusy || !player) return;
    const i = document.getElementById('chat-input'); if (!i) return;
    const msg = i.value.trim(); if (!msg) return;
    _chatBusy = true;
    const btn = document.getElementById('chat-send-btn'); if (btn) btn.disabled = true;
    _chatPost({ action: 'send', message: msg, to: _chatWith || '' }, r => {
      _chatBusy = false; if (btn) btn.disabled = false;
      if (!r) return;
      if (r.error) { // muted / spam → เตือนใต้ช่องพิมพ์ (ไม่ใช้ alert กันขวางเกม)
        if (r.msg) addLog([{ type: 'dead', msg: r.msg }]);
        return;
      }
      i.value = '';
      if (!_chatWith) { _sayUntil = Date.now() + XHRPG_SAY_MS; _sayText = msg.slice(0, 60); } // 💬 บับเบิลบนหัวเราเอง (ทันที ไม่รอ poll)
      renderChat();
    });
  }
  function renderRank() {
    const box = document.getElementById('rank-list');
    if (!box) return;
    box.innerHTML = '<div class="rank-loading">' + T('กำลังโหลด...') + '</div>';
    const uid = player ? player.line_uid : '';
    $.getJSON('xhrpg_leaderboard.php', { tab: rankCurrentTab, uid, cc: rankCC === 'ALL' ? '' : rankCC })
      .done(d => {
        if (!d.ok) { box.innerHTML = '<div class="rank-loading">' + T('โหลดไม่ได้') + '</div>'; return; }
        const _ccBarHtml = rankCurrentTab === 'country' ? '' : _rankCCBar(d.ccs); // 🌐 แถบธงกรอง (แท็บประเทศไม่ต้องกรอง)

        // ── 🌍 อันดับประเทศ: พลังรบรวม Top 1-10 ต่อประเทศ ──
        if (rankCurrentTab === 'country') {
          if (!d.list || !d.list.length) { box.innerHTML = '<div class="rank-loading">' + T('ยังไม่มีข้อมูลประเทศ') + '</div>'; return; }
          box.innerHTML = d.list.map(r => {
            const medal = r.rank === 1 ? '🥇' : r.rank === 2 ? '🥈' : r.rank === 3 ? '🥉' : r.rank;
            return `<div class="rank-row">
              <div class="rank-top">
                <div class="rank-num">${medal}</div>
                <div class="rank-name" style="font-size:15px">${_ccFlag(r.cc)}${r.cc}</div>
                <div class="rank-score">
                  <div class="rank-score-val">⚔️ ${Number(r.power).toLocaleString()}</div>
                  <div class="rank-score-label">${T('พลังรบรวม')}</div>
                  <div class="rank-score-label">${T('นับจาก Top {a} · ผู้เล่น {b} คน', {a: r.cnt, b: r.players})}</div>
                </div>
              </div>
            </div>`;
          }).join('');
          return;
        }

        // ── 🏛️ สนามประลอง: อันดับสังหาร "วันนี้" (รีเซ็ตเที่ยงคืน — server ส่งเฉพาะแถว CURDATE) ──
        if (rankCurrentTab === 'colosseum') {
          const _ce = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
          const _colRow = (r, hl) => {
            const medal = r.rank === 1 ? '🥇' : r.rank === 2 ? '🥈' : r.rank === 3 ? '🥉' : r.rank;
            return `<div class="rank-row" style="${hl ? 'border:2px solid #f59e0b;background:#fffbeb' : ''}">
              <div class="rank-top">
                <div class="rank-num">${medal}</div>
                <div class="rank-name">${r.cc ? _ccFlag(r.cc) : ''}${_ce(r.name)}</div>
                <div class="rank-score">
                  <div class="rank-score-val">⚔️ ${Number(r.kills).toLocaleString()}</div>
                  <div class="rank-score-label">💀 ${Number(r.deaths).toLocaleString()} · K/D ${r.kd}</div>
                </div>
              </div>
            </div>`;
          };
          const _hdr = '<div style="text-align:center;font-size:10.5px;color:#92400e;background:#fef3c7;border-radius:8px;padding:4px 8px;margin-bottom:8px;font-weight:600">' + T('🏛️ อันดับสังหารวันนี้ — รีเซ็ตเที่ยงคืน') + '</div>';
          if (!d.list || !d.list.length) { box.innerHTML = _ccBarHtml + _hdr + '<div class="rank-loading">' + T('วันนี้ยังไม่มีการต่อสู้ในสนาม') + '</div>'; return; }
          let _h = _ccBarHtml + _hdr + d.list.map(r => _colRow(r, d.me && r.uid === d.me.uid)).join('');
          if (d.me && !d.list.some(r => r.uid === d.me.uid)) _h += _colRow(d.me, true); // แถวเราหลุด Top 50 — ต่อท้าย
          box.innerHTML = _h;
          return;
        }

        // ── MVP tab ──
        if (rankCurrentTab === 'mvp') {
          if (!d.list || d.list.length === 0) {
            box.innerHTML = _ccBarHtml + '<div class="rank-loading">' + T('ยังไม่มีการกำจัด MVP') + '</div>';
            return;
          }
          const _esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); // (#8) escape ก่อนใส่ innerHTML (killer_name เป็น user input)
          const mvpRowHtml = r => {
            // drop_item = ของทุกชิ้นที่ได้ join ด้วย \n (แถวเก่า = ชิ้นเดียว ไม่มี \n → split ได้ 1 ชิป · backward-compat)
            const _drops = r.drop_item ? String(r.drop_item).split('\n').filter(Boolean) : [];
            const dropRow = _drops.length
              ? `<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:6px">${_drops.map(d => `<span style="background:#f3e8ff;color:#7c3aed;border-radius:6px;padding:2px 8px;font-size:10px;font-weight:600;white-space:nowrap">${_esc(_mvpDropT(d))}</span>`).join('')}</div>`
              : `<div style="margin-top:6px"><span style="color:#cbd5e1;font-size:9px">${T('— ไม่มี drop')}</span></div>`;
            return `<div style="display:flex;background:#fff;border:1px solid #94a3b8;border-radius:12px;margin-bottom:7px;overflow:hidden">
              <div style="flex:1;min-width:0;padding:8px 10px">
                <div style="display:flex;align-items:center;justify-content:space-between;gap:6px">
                  <div style="display:flex;align-items:center;gap:6px;min-width:0">
                    ${r.killer_cc ? `<span style="flex:none;display:inline-flex;align-items:center">${_ccFlag(r.killer_cc)}</span>` : ''}
                    <span style="font-size:13px;font-weight:600;color:#111;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">🧑 ${_esc(r.killer_name)}</span>
                    <span style="flex:none;background:#dbeafe;color:#1d4ed8;border-radius:6px;padding:1px 6px;font-size:10px;font-weight:500">Lv.${r.killer_lv}</span>
                  </div>
                  <span style="flex:none;font-size:10px;color:#475569;white-space:nowrap">${_esc(_mvpAgoT(r.ago))}</span>
                </div>
                <div style="display:flex;align-items:center;gap:8px;margin-top:5px">
                  <div style="display:flex;align-items:center;gap:5px;min-width:0;flex:1">
                    <span style="font-size:10px;color:#475569;flex:none">⚔️</span>
                    <span style="font-size:14px;flex:none">${_esc(r.mon_emoji)}</span>
                    <span style="font-size:12px;font-weight:600;color:#dc2626;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_esc(T(r.mon_name || ''))} Lv.${r.mon_lv}</span>
                  </div>
                  <span style="flex:none;background:#f1f5f9;color:#475569;border-radius:6px;padding:1px 6px;font-size:9px;white-space:nowrap">Zone ${r.zone}</span>
                </div>
                ${dropRow}
              </div>
            </div>`;
          };
          let html = d.list.map(mvpRowHtml).join('');
          html += `<div class="rank-footer">${T('{a} การกำจัดล่าสุด', {a: d.list.length})}</div>`; // (#7) นับจริง ไม่ hardcode 100
          box.innerHTML = _ccBarHtml + html;
          return;
        }

        // ── Normal tabs ──
        const me = d.me;
        const scoreFn = r => {
          if (rankCurrentTab === 'gold')  return { val: r.gold.toLocaleString(), label: 'Gold' };
          return { val: 'Lv.' + r.lv, label: 'EXP ' + r.exp.toLocaleString(), rag: (r.lv >= 50 && r.rag_lv) ? r.rag_lv : 0 }; // 🌟 Ragnalok Lv (เฉพาะคนตัน Lv.50)
        };
        const _rEsc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
        const rowHtml = r => {
          const medal = r.rank === 1 ? '🥇' : r.rank === 2 ? '🥈' : r.rank === 3 ? '🥉' : r.rank;
          const isMe  = me && r.uid === me.uid;
          const sc    = scoreFn(r);
          return `<div class="rank-row${isMe?' me':''}">
            <div class="rank-top">
              <div class="rank-num">${medal}</div>
              <div class="rank-name">${r.cc ? _ccFlag(r.cc) : ''}${_rEsc(r.name)}</div>
              <div class="rank-score">
                <div class="rank-score-val">${sc.val}</div>
                ${sc.rag ? `<div class="rank-score-label" style="color:#b45309;font-weight:700">🌟 Ragnalok Lv.${sc.rag}</div>` : ''}
                <div class="rank-score-label">${sc.label}</div>
              </div>
            </div>
            <div class="rank-body">
              ${_lbCast(r)}
              <div class="rank-chips">
                <div class="rank-chip">🎽 <span>${r.eq}/${r.max.eq}</span></div>
                <div class="rank-chip">🏆 <span>${r.tr}/${r.max.tr}</span></div>
                <div class="rank-chip">🤖 <span>${r.hw}/${r.max.hw}</span></div>
                <div class="rank-chip">🔧 <span>${r.wp}/${r.max.wp}</span></div>
                <div class="rank-chip">⚡ <span>${r.sp}/${r.max.sp}</span></div>
                <div class="rank-chip">🛸 <span>${r.hp2}/${r.max.hp}</span></div>
              </div>
            </div>
          </div>`;
        };

        let html = '';
        if (me && d.list.findIndex(r => r.uid === me.uid) === -1) {
          html += rowHtml(me) + '<div class="rank-divider"></div>';
        }
        html += d.list.map(rowHtml).join('');
        box.innerHTML = _ccBarHtml + html;
      })
      .fail(() => { box.innerHTML = '<div class="rank-loading">' + T('โหลดไม่ได้') + '</div>'; });
  }

  function notYetOpen() {
    const el = document.getElementById('not-yet-toast');
    if (el) { el.style.opacity = '1'; setTimeout(() => { el.style.opacity = '0'; }, 2000); return; }
    const toast = document.createElement('div');
    toast.id = 'not-yet-toast';
    toast.textContent = 'ยังไม่เปิด';
    toast.style.cssText = 'position:fixed;bottom:140px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.75);color:#fff;padding:8px 20px;border-radius:20px;font-size:15px;z-index:9999;pointer-events:none;transition:opacity 0.4s;';
    document.body.appendChild(toast);
    setTimeout(() => { toast.style.opacity = '0'; setTimeout(() => toast.remove(), 400); }, 2000);
  }

