            if (['🦾', '🪓', '⚡'].includes(ic)) return smoothed('robot', player.robot_x ?? (player.x + 15), player.robot_y ?? player.y); // key เดียวกับ drawRobot
            if (ic === '🐾') return { x: _mpX ?? (player.pet_x ?? player.x), y: _mpY ?? (player.pet_y ?? player.y) }; // สัตว์เลี้ยง — ตำแหน่ง lerp ที่วาดจริง
