                const ry = (typeof player.robot_y === 'number' && isFinite(player.robot_y)) ? player.robot_y : player.y;
                const ROBOT_ICONS = ['🦾', '🪓', '⚡'];
                const isHouse = e.icon === '🏠' || e.icon === '🏠⚡';
