        bonusHtml = `<span style="font-size:10px;font-weight:700;color:${t.c};background:${t.bg};border-radius:5px;padding:1px 7px;${t.glow?'box-shadow:0 0 6px #eab308;':''}">+${_roll.v} ${_roll.label}</span>${bestTxt}`;
