  // ── Panel popup ───────────────────────────────────────────
  let openPanel = null;
  function togglePanel(name) {
    if (openPanel === name) { closePanel(); return; }
    closePanel();
    openPanel = name;
    document.getElementById('panel-overlay').classList.add('open');
    document.getElementById('panel-' + name).classList.add('open');
    document.getElementById('mbtn-' + name)?.classList.add('active');
    if (name === 'gun')     renderGuns();   // เรนเดอร์ตอนเปิด (poll ไม่เรนเดอร์ให้แล้ว เพื่อลดกระตุก)
    if (name === 'item')    renderItems();
    if (name === 'stat')    renderStats();
    if (name === 'robot')   renderRobot();
    if (name === 'house')   renderHouse();
    if (name === 'card')    renderCard();
    if (name === 'pet')     renderPet();
    if (name === 'rank')    renderRank();
    if (name === 'premium') { _topupPromo = -1; renderPremium(); } // เช็คสิทธิโปร ×1.5 ใหม่ทุกครั้งที่เปิด (กันค่าค้างหลังเติม)
    if (name === 'market')  { mktMode='buy'; mktSellOpen=false; mktSellStep=1; mktBuyStep=1; mktSelItem=null; mktSelListing=null; mktSelGroup=null; mktBuyCat='all'; mktBuySearch=''; window._mktListingsCache=null; window._mktMyCache=null; renderMarket(); }
    if (name === 'guide')   renderGuide();
    if (name === 'chat')    { renderChat(); _chatBadgeUpd(); setTimeout(() => document.getElementById('chat-input')?.focus(), 60); }
    if (name === 'log')     { const el = document.getElementById('event-log'); if (el) el.scrollTop = el.scrollHeight; } // เนื้อหา static (#event-log) — แค่เลื่อนลงล่างสุด
  }
  function closePanel() {
    if (openPanel) {
      document.getElementById('panel-' + openPanel).classList.remove('open');
      document.getElementById('mbtn-' + openPanel)?.classList.remove('active');
    }
    document.getElementById('panel-overlay').classList.remove('open');
    openPanel = null;
  }

  let travelingToSpot = null; // { spotId, cx, cy, radius } — null = ไม่ได้เดินทาง

  function updateSpotSelect() {
    const sel = document.getElementById('spot-select');
    if (!sel) return;
    if (!sel.dataset.built) {
      sel.innerHTML = '<option value="">' + T('🗺️ เลือกจุดหมาย') + '</option>' +
        spotDefs.map((s, i) =>
          `<option value="${i}">${s.emoji} Lv.${s.lv_min}-${s.lv_max} ${T(s.name)}</option>`
        ).join('');
      sel.dataset.built = '1';
    }
    // sync value
    if (!travelingToSpot) sel.value = '';
  }

  // leash การเดิน = รัศมีที่มอนโซนนั้นเกิด (spotDefs[sid].radius px)/3 = ม. + buffer 8m → ผู้เล่นอยู่ในโซน ไม่ออกไปไกล
  const _zoneLeashM = (sid) => Math.round((((spotDefs[sid] || {}).radius) || 750) / 3) + 8;
  function checkArrival() {
    if (!travelingToSpot || !player) return;
    const dx = player.x - travelingToSpot.cx;
    const dy = player.y - travelingToSpot.cy;
    const dist = Math.sqrt(dx*dx + dy*dy);
    // หยุดเมื่อห่างจุดกลางโซน ~30m (90px) → ไม่มุดกลางเป๊ะ แต่ใกล้พอเข้าตีได้ทันที (เดิม 80m ไกลไป)
    if (dist <= 90) {
      player.explore_cx = player.x; // ศูนย์ leash = จุดที่หยุด (~30m จากกลางโซน) → บอทวนฟาร์มรอบจุดนี้
      player.explore_cy = player.y;
      exploreRadius = 100; _syncExploreBtns(); // หลังถึงเป้า → รัศมี 100m (ฟาร์มกระชับรอบจุดที่หยุด · ตรงปุ่ม er-100 → ไฮไลต์ชัด)
      travelingToSpot = null;
      targetMonsterId = null; // ล้างเป้าหมาย → server เลือกเป้าใหม่ในโหมดโจมตีปกติ
      const sel = document.getElementById('spot-select');
      if (sel) sel.value = '';
      addLog([{type:'levelup', msg: T('✅ ถึงโซนแล้ว! เริ่มโจมตี (หยุดรอบนอก ~80m)')}]);
    }
  }

  // แสดงปุ่ม icon บอส (MVP) ข้าง dropdown — กดแล้วเดินไปหาบอส
  let _bossBtnSig = '';
  function renderBossButtons() {
    const box = document.getElementById('boss-btns');
    if (!box) return;
    // sig รวม %HP (ปัดหยาบ) → rebuild เมื่อบอสเปลี่ยน/HP เปลี่ยน (บอสไม่กี่ตัว rebuild เบามาก)
    const sig = bosses.map(b => `${b.id}:${Math.round((b.hp/Math.max(1,b.hp_max))*20)}`).join(',');
    if (sig === _bossBtnSig) return;
    _bossBtnSig = sig;
    if (!bosses.length) { box.innerHTML = ''; return; }
    box.innerHTML = bosses.map(b => {
      const pct = Math.max(0, Math.min(100, Math.round((b.hp / Math.max(1, b.hp_max)) * 100)));
      const col = pct > 50 ? '#22c55e' : pct > 25 ? '#f59e0b' : '#ef4444';
      return `<button class="boss-btn" title="${T(b.name)} Lv.${b.lv} — HP ${pct}%" onclick="xhrpg.goToBoss(${b.id})"
        style="position:relative;margin-left:4px;padding:2px 6px 5px;border:1px solid #ef4444;border-radius:8px;background:#7f1d1d;color:#fff;font-size:13px;cursor:pointer;line-height:1.3;overflow:hidden">
        ${b.emoji}<span style="font-size:9px;margin-left:1px">Lv${b.lv}</span>
        <span style="position:absolute;left:2px;right:2px;bottom:1px;height:3px;background:rgba(0,0,0,.45);border-radius:2px">
          <span style="display:block;height:100%;width:${pct}%;background:${col};border-radius:2px"></span>
        </span></button>`;
    }).join('');
  }

  function goToBoss(bossId) {
    if (!player) return;
    const b = bosses.find(x => x.id === bossId);
    if (!b) { addLog([{type:'default', msg:T('บอสตัวนี้หายไปแล้ว')}]); return; }
    // เดินไปหาบอสอย่างเร็ว (แบบเดียวกับเดินไป zone) — หยุดห่างบอส ~80m (checkArrival ≤240px) แล้วบอทค่อย approach เข้าตี
    travelingToSpot = { bossId, cx: b.x, cy: b.y, radius: 40 };
    player.explore_cx = b.x; player.explore_cy = b.y;
    if (!botEnabled) toggleBot();
    render(); updateHUD();
    addLog([{type:'retreat', msg: T('{a} กำลังไปล่าบอส {b} (Lv.{c})!', {a: b.emoji, b: T(b.name), c: b.lv})}]);
  }

  function goToSpot(spotId) {
    if (spotId === '' || spotId === null) {
      travelingToSpot = null;
      currentSpotId = 0; exploreRadius = 300; _syncExploreBtns(); // ล้างเลือก = กลับ default 300m (ตรงปุ่ม er-300)
      if (player) { player.explore_cx = SPAWN_X; player.explore_cy = SPAWN_Y; }
      return;
    }
    spotId = parseInt(spotId);
    const spot = spotDefs[spotId];
    if (!spot || !player) return;
    currentSpotId = spotId;
    // เดินไป (ไม่วาร์ป) — ตั้งปลายทาง = กลางโซน, server เดินไปเร็ว, "ถึง" เมื่อเข้าจุดศูนย์กลางจริง (checkArrival ≤15m)
    travelingToSpot = { spotId, cx: spot.cx, cy: spot.cy, radius: spot.radius };
    player.explore_cx = spot.cx; player.explore_cy = spot.cy; // ปลายทางเดินทาง (server travel mode วิ่งไปทางนี้)
    if (!botEnabled) toggleBot();
    render(); updateHUD();
    addLog([{type:'retreat', msg: T('{a} กำลังเดินไป {b} (Lv.{c}-{d})...', {a: spot.emoji, b: T(spot.name), c: spot.lv_min, d: spot.lv_max})}]);
    // ไม่ล้าง select ระหว่างเดินทาง — checkArrival จะล้างตอนถึง
  }

  function goToHouse() {
    if (!player || !(player.house_lv >= 1)) { addLog([{type:'dead',msg:T('ยังไม่มียานบิน')}]); return; }
    // ตั้ง explore target เป็นยานบิน แล้วเปิด bot นำทาง
    player.explore_cx = player.house_x;
    player.explore_cy = player.house_y;
    player.explore_tx = player.house_x;
    player.explore_ty = player.house_y;
    if (!botEnabled) toggleBot();
    addLog([{type:'retreat', msg:T('🛸 กำลังเดินทางไปยานบิน...')}]);
    closePanel();
  }

  function warpHome() {
    if (!player) return;
    // 🛸 ยาน Orion บินตามตัวแล้ว — Warp กลับยานบิน = วาร์ปกลางแผนที่ปัจจุบัน (ไม่ส่ง tx/ty → server ใช้ spawn ของ map)
    $.post(baseUrl + 'xhrpg_warp.php', { line_uid: player.line_uid })
      .done(res => {
        const d = typeof res === 'string' ? JSON.parse(res) : res;
        if (d.ok) {
          player.x = d.x; player.y = d.y;
          player.explore_cx = d.x; player.explore_cy = d.y;
          delete smoothPos['player']; // วาร์ป = ตั้งใจย้ายตัวทันที → snap ตัว+กล้อง ไม่ให้ glide วิ่งไล่ข้ามแมป (ระยะ <260px เดิมจะไหลตาม ~1 วิ)
          render(); updateHUD();
          addLog([{type:'retreat', msg: T('🛸 Warp กลางแผนที่!')}]);
        }
      });
  }

  // ── เปลี่ยนแผนที่ (multi-map) ──────────────────────────────────────────────
  const MAP_DEFS = [{id:1,name:'ทุ่งกลาง',emoji:'🌿',req:1},{id:2,name:'ทะเลทรายนิรันดร์',emoji:'🏜️',req:25},{id:3,name:'ดินแดนเยือกแข็ง',emoji:'❄️',req:40},{id:4,name:'สนามประลอง',emoji:'🏛️',req:20}];
  // ── 🏛️ สนามประลอง (map 4): จำนวนคนในสนาม + เกราะจุดเกิด + ป้ายมุมจอ ──
  let _colN = 0, _colShUntil = 0;
  function _colBadgeUpd() {
    let el = document.getElementById('col-badge');
    if (currentMap !== 4) { if (el) el.remove(); return; }
    if (!el) {
      el = document.createElement('div');
      el.id = 'col-badge';
      el.style.cssText = 'position:absolute;top:120px;right:5px;width:84px;box-sizing:border-box;text-align:center;background:rgba(120,53,15,.85);color:#fde68a;font-size:9.5px;font-weight:700;padding:4px 2px;border-radius:7px;border:1px solid #f59e0b;pointer-events:none;z-index:10;white-space:nowrap';
      (document.querySelector('.map-wrap') || document.body).appendChild(el); // ใต้ปุ่ม 🌙 OFFLINE (top:93+24+3)
    }
    el.textContent = T('🏛️ {a} คน', {a: _colN});
  }
  function warpToMap(mapId) {
    mapId = mapId|0;
    if (!player || mapId === currentMap) { closeMapSelect(); return; }
    $.post(baseUrl + 'xhrpg_warp.php', { line_uid: player.line_uid, target_map: mapId })
      .done(res => {
        let d; try { d = typeof res === 'string' ? JSON.parse(res) : res; }
        catch (e) { closeMapSelect(); alert(T('วาร์ปไม่สำเร็จ: ตอบกลับผิดรูปแบบ')); return; }
        if (d && d.ok) {
          currentMap = d.map; player.map = d.map;
          player.x = d.x; player.y = d.y; player.explore_cx = d.x; player.explore_cy = d.y;
          delete smoothPos['player'];                 // snap ตัว+กล้อง (วาร์ปข้าม map)
          currentSpotId = 0; travelingToSpot = null;  // รีเซ็ตโซนที่เลือก → leash ใช้ spot 0 ของ map ใหม่
          const _sel = document.getElementById('spot-select'); if (_sel) _sel.dataset.built = ''; // dropdown สร้างใหม่ตาม spots map ใหม่
          _haveMon = false;                            // force have_static=0 → server ส่ง spots ของ map ใหม่
          buildGround();                               // สร้างพื้น map ใหม่ (ทราย/หญ้า)
          closeMapSelect(); render(); updateHUD();
          const _md = MAP_DEFS.find(m => m.id === mapId);
          const nm = _md ? T(_md.name) : T('แผนที่ {a}', {a: mapId});
          addLog([{type:'retreat', msg: T('🗺️ วาร์ปไป {a}!', {a: nm})}]);
        } else if (d && d.error === 'level_locked') {
          closeMapSelect(); alert(d.msg || T('ต้องถึง Lv.{a} ก่อนวาร์ป', {a: d.need || 25}));
        } else { closeMapSelect(); alert(T('วาร์ปไม่สำเร็จ: ') + ((d && d.error) || '?')); }
      })
      .fail(xhr => { closeMapSelect(); addLog([{type:'dead', msg: T('❌ วาร์ปไม่สำเร็จ (เชื่อมต่อไม่ได้ HTTP {a})', {a: (xhr && xhr.status)})}]); });
  }
  function openMapSelect() {
    if (!player || document.getElementById('mapsel-ov')) return;
    const lv = player.lv || 1, cur = currentMap;
    const ov = document.createElement('div');
    ov.id = 'mapsel-ov';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:99999;display:flex;align-items:center;justify-content:center';
    ov.onclick = (e) => { if (e.target === ov) closeMapSelect(); };
    ov.innerHTML = '<div style="background:#fff;border-radius:14px;padding:16px;width:290px;max-width:90vw;box-shadow:0 8px 32px rgba(0,0,0,.35)">' +
      '<div style="font-weight:800;font-size:15px;margin-bottom:12px;text-align:center;color:#334155">' + T('🗺️ เปลี่ยนแผนที่') + '</div>' +
      MAP_DEFS.map(m => {
        const isCur = m.id === cur, lock = lv < m.req && !isCur;
        let sub = isCur ? T('📍 อยู่ที่นี่') : (lock ? T('🔒 ต้องถึง Lv.{a}', {a: m.req}) : T('พร้อมวาร์ป · Lv.{a}+', {a: m.req}));
        if (m.id === 4) sub += '<div style="font-size:10px;color:#b45309;font-weight:700;margin-top:1px">' + T('⚔️ PVP อิสระ · {a} คนในสนาม', {a: _colN}) + '</div>'; // 🏛️ จำนวนคนสดจาก poll ล่าสุด
        return '<button ' + ((isCur || lock) ? 'disabled ' : '') + 'onclick="xhrpg.warpToMap(' + m.id + ')" ' +
          'style="display:flex;align-items:center;gap:12px;width:100%;padding:11px;margin-bottom:8px;border-radius:10px;border:2px solid ' +
          (isCur ? '#16a34a' : '#e5e7eb') + ';background:' + (isCur ? '#dcfce7' : (lock ? '#f1f5f9' : '#fff')) +
          ';cursor:' + ((isCur || lock) ? 'default' : 'pointer') + ';opacity:' + (lock ? '.55' : '1') + '">' +
          '<span style="font-size:24px">' + m.emoji + '</span>' +
          '<span style="flex:1;text-align:left"><div style="font-weight:700;color:#1e293b">' + T(m.name) + '</div>' +
          '<div style="font-size:11px;color:' + (isCur ? '#16a34a' : '#94a3b8') + '">' + sub + '</div></span>' +
          (isCur ? '<span style="color:#16a34a;font-size:18px">✓</span>' : (lock ? '' : '<span style="color:#3b82f6;font-size:16px">➜</span>')) +
          '</button>';
      }).join('') +
      '<button onclick="xhrpg.closeMapSelect()" style="width:100%;padding:9px;margin-top:2px;border:none;border-radius:10px;background:#e2e8f0;color:#475569;font-weight:600;cursor:pointer">' + (LANG() === 'th' ? 'ปิด' : T('ปิดหน้าต่าง')) + '</button>' +
      '</div>';
    document.body.appendChild(ov);
  }
  function closeMapSelect() { const ov = document.getElementById('mapsel-ov'); if (ov) ov.remove(); }

  function logout() {
    _pollStopped = true;
    if (pollTimer) clearTimeout(pollTimer);
    closePanel();
    const isGoogle = player && String(player.line_uid ?? '').startsWith('google_');
    if (isGoogle) {
      // ล้าง PHP session แล้ว reload หน้าปกติ (ไม่มี ?auth=google)
      $.post(baseUrl + 'xhrpg_logout.php').always(() => {
        window.location.replace(window.location.pathname);
      });
    } else if (typeof liff !== 'undefined' && liff.isLoggedIn()) {
      liff.logout();
      window.location.replace(window.location.pathname);
    } else {
      startDemo(baseUrl);
    }
  }

