  function getSkills() {
    const raw = player.skills;
    if (!raw) return {};
    return typeof raw === 'object' ? raw : JSON.parse(raw || '{}');
  }

  function drawTurrets() {
    if (!player) return;
    const _cnt = player.cannon_turret; // 💣 ป้อมปืนใหญ่ (skill turret_cannon)
    const _hasCn = _cnt && _cnt.x != null; // server ลบ field เองเมื่อหมดอายุ (cannon_tick) — ไม่เทียบ clock ฝั่งเครื่องผู้เล่น (เพี้ยนแล้วปืนล่องหน)
    if ((!Array.isArray(player.turrets) || !player.turrets.length) && !_hasCn) return;
    const { scale } = getCameraTransform();
    const fs = Math.round(17 * scale);
    if (_hasCn) { // 💣 ปืนใหญ่ — วาด vector เอง (ฐานเหล็ก + ตัวป้อม + ลำกล้องหนายาว โทนส้ม) หมุนเข้าเป้า + วงระยะส้มจาง
      const cs = toScreen(_cnt.x, _cnt.y);
      if (!_hideLines) {
        const rPx = 300 * scale; // 💣 ระยะยิง 100m (คงที่ · sync server)
        ctx.beginPath(); ctx.arc(cs.x, cs.y, rPx, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(249,115,22,0.35)'; ctx.setLineDash([5, 5]); ctx.lineWidth = 1; ctx.stroke(); ctx.setLineDash([]);
      }
      let best = Infinity, nm = null;
      for (const m of monsters) { if (m.is_dead) continue; const d = (m.x - _cnt.x) ** 2 + (m.y - _cnt.y) ** 2; if (d < best) { best = d; nm = m; } }
      let tgx = _cnt.x + 1, tgy = _cnt.y;
      if (nm) { const _sp = smoothed('m' + nm.id, nm.x, nm.y); tgx = _sp.x; tgy = _sp.y; }
      const ang = Math.atan2(tgy - _cnt.y, tgx - _cnt.x);
      const u = 1.15 * scale; // หน่วยสเกลปืนใหญ่
      ctx.save();
      ctx.translate(cs.x, cs.y); ctx.lineJoin = 'round';
      ctx.strokeStyle = '#1e293b'; ctx.lineWidth = Math.max(1, 1.6 * u);
      // ฐานแท่นเหล็ก (วงกลมซ้อน)
      ctx.fillStyle = '#475569'; ctx.beginPath(); ctx.arc(0, 0, 11 * u, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#64748b'; ctx.beginPath(); ctx.arc(0, 0, 8 * u, 0, Math.PI * 2); ctx.fill();
      // หมุนตามทิศเป้า: ลำกล้องหนายาว + ปากกระบอก
      ctx.rotate(ang);
      ctx.fillStyle = '#7c2d12'; ctx.fillRect(3 * u, -3.2 * u, 15 * u, 6.4 * u); ctx.strokeRect(3 * u, -3.2 * u, 15 * u, 6.4 * u); // ลำกล้อง (น้ำตาลเข้ม)
      ctx.fillStyle = '#ea580c'; ctx.fillRect(16 * u, -4 * u, 4 * u, 8 * u); ctx.strokeRect(16 * u, -4 * u, 4 * u, 8 * u);       // ปากกระบอก (ส้ม)
      // ตัวป้อมกลาง (โดมส้ม)
      ctx.fillStyle = '#f97316'; ctx.beginPath(); ctx.arc(0, 0, 5.5 * u, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#fed7aa'; ctx.beginPath(); ctx.arc(-1.5 * u, -1.5 * u, 1.8 * u, 0, Math.PI * 2); ctx.fill(); // ไฮไลต์
      ctx.restore();
      ctx.font = `${Math.round(11 * scale)}px serif`; ctx.textAlign = 'center';
      ctx.fillText('💣', cs.x, cs.y - 16 * u); // ป้ายปืนใหญ่
    }
    if (!Array.isArray(player.turrets)) return;
    const _shLvD = parseInt(getSkills().turret_shock) || 0; // 🌩️ รัศมีออร่า (วงฟ้ากระพริบ)
    const _shRD  = (10 + Math.max(0, _shLvD - 1)) * 3;
    player.turrets.forEach(tu => {
      if (!tu) return;
      const s = toScreen(tu.x, tu.y);
      if (!_hideLines) {
        const rPx = (180 + 3 * ((tu.lv || 1) - 1) + (parseInt(getSkills().twin_turret)||0) * 3) * scale; // 60m base +1m/Lv + ป้อมคู่ ตรงกับ server
        ctx.beginPath(); ctx.arc(s.x, s.y, rPx, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(239,68,68,0.35)'; ctx.setLineDash([5, 5]); ctx.lineWidth = 1; ctx.stroke(); ctx.setLineDash([]);
      }
      if (tu.sh && _shLvD > 0) { // 🌩️ SHOCK: วงกลมฟ้าจางกระพริบรอบป้อม (แทน effect ระเบิดเดิม)
        const _pu = 0.10 + 0.14 * Math.abs(Math.sin(Date.now() / 260)); // alpha 0.10–0.24 (จางๆ กระพริบ)
        ctx.save();
        ctx.globalAlpha = _pu;
        ctx.fillStyle = '#38bdf8';
        ctx.beginPath(); ctx.arc(s.x, s.y, _shRD * scale, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = Math.min(0.5, _pu + 0.18);
        ctx.strokeStyle = '#7dd3fc'; ctx.lineWidth = Math.max(1, 1.4 * scale);
        ctx.beginPath(); ctx.arc(s.x, s.y, _shRD * scale, 0, Math.PI * 2); ctx.stroke();
        ctx.restore();
        startAnim(); // กระพริบต่อเนื่อง
      }
      // ป้อมปืน sprite (barrel ชี้ลง → หมุนเข้าเป้าใกล้สุด) · fallback 🗼
      const timg = SUM['turret'];
      if (timg && timg.complete && timg.naturalWidth) {
        let best = Infinity, nm = null;
        for (const m of monsters) { if (m.is_dead) continue; const d = (m.x-tu.x)**2+(m.y-tu.y)**2; if (d<best){best=d;nm=m;} }
        let tgx = tu.x, tgy = tu.y - 1;
        if (nm) { const _sp = smoothed('m' + nm.id, nm.x, nm.y); tgx = _sp.x; tgy = _sp.y; } // หันตามตำแหน่ง smoothed (ที่มอนถูกวาด/เลเซอร์ยิงไป)
        const ang = Math.atan2(tgy - tu.y, tgx - tu.x);
        const sz = 24 * scale; // −30% (จาก 34)
        ctx.save(); ctx.imageSmoothingEnabled = false;
        ctx.translate(s.x, s.y); ctx.rotate(ang + Math.PI / 2); // barrel สไปรต์ชี้ขึ้น (local −Y) → หมุนให้ปากกระบอกหันเข้าเป้า (กันยิงออกท้าย)
        ctx.drawImage(timg, -sz / 2, -sz / 2, sz, sz);
        ctx.restore();
      } else {
        ctx.font = `${fs}px serif`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.shadowColor = '#22c55e'; ctx.shadowBlur = 8 * scale;
        ctx.fillText('🗼', s.x, s.y);
        ctx.shadowBlur = 0; ctx.textBaseline = 'alphabetic';
      }
    });
  }

  // 🗼 ป้อมของผู้เล่นอื่น (จาก others[].tr = [{x,y,lv},...]) — วาดเหมือนป้อมเรา แต่วงระยะสีฟ้าจางแยกเจ้าของ
  function drawOtherTurrets() {
    if (!others || !others.length) return;
    const { scale } = getCameraTransform();
    const timg = SUM['turret'];
    const fs = Math.round(17 * scale);
    others.forEach(o => {
      if (o.is_ghost || !Array.isArray(o.tr) || !o.tr.length) return;
      o.tr.forEach(tu => {
        if (!tu) return;
        const s = toScreen(tu.x, tu.y);
        if (s.x < -40 || s.x > canvas.width + 40 || s.y < -40 || s.y > canvas.height + 40) return;
        if (!_hideLines) {
          const rPx = (180 + 3 * ((tu.lv || 1) - 1)) * scale; // ระยะโดยประมาณ (ไม่รู้สกิลป้อมคู่ของเพื่อน)
          ctx.beginPath(); ctx.arc(s.x, s.y, rPx, 0, Math.PI * 2);
          ctx.strokeStyle = 'rgba(148,163,184,0.18)'; ctx.setLineDash([5, 5]); ctx.lineWidth = 1; ctx.stroke(); ctx.setLineDash([]); // วงเทาจาง (ป้อมเพื่อน)
        }
        if (timg && timg.complete && timg.naturalWidth) {
          let best = Infinity, nm = null;
          for (const m of monsters) { if (m.is_dead) continue; const d = (m.x-tu.x)**2+(m.y-tu.y)**2; if (d<best){best=d;nm=m;} }
          let tgx = tu.x, tgy = tu.y - 1;
          if (nm) { const _sp = smoothed('m' + nm.id, nm.x, nm.y); tgx = _sp.x; tgy = _sp.y; }
          const ang = Math.atan2(tgy - tu.y, tgx - tu.x);
          const sz = 24 * scale;
          ctx.save(); ctx.globalAlpha = 0.45; ctx.imageSmoothingEnabled = false; // 🩶 ป้อมเพื่อน = เทาจาง แยกจากป้อมเรา
          ctx.filter = 'grayscale(1)';
          ctx.translate(s.x, s.y); ctx.rotate(ang + Math.PI / 2);
          ctx.drawImage(timg, -sz / 2, -sz / 2, sz, sz);
          ctx.restore();
        } else {
          ctx.font = `${fs}px serif`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
          ctx.save(); ctx.globalAlpha = 0.45; ctx.filter = 'grayscale(1)';
          ctx.fillText('🗼', s.x, s.y);
          ctx.restore(); ctx.textBaseline = 'alphabetic';
        }
      });
    });
  }

  function _turretTierStrip() {
    const mask  = parseInt(player.turret_tier_enabled) || 1; // bitmask tier ที่เปิด (ลอกจากปืน)
    const hLv   = player.house_lv || 0;
    const mult  = [1.0,1.2,1.4,1.6,1.8,2.0];
    let cells = '';
    for (let t = 1; t <= 6; t++) {
      const locked  = hLv < AMMO_TIER_UNLOCK_LV[t-1];
      const enabled = !!(mask & (1 << (t-1)));
      const owned   = _ammoOwned('pistol', t);
      const onclick = locked ? '' : `xhrpg.toggleAmmTier('turret',${t},${enabled?0:1})`;
      cells += `<div onclick="${onclick}" style="text-align:center;padding:4px 1px;border-radius:6px;cursor:${locked?'default':'pointer'};border:${enabled?'2px solid #22c55e':'1px solid #94a3b8'};background:${enabled?'#f0fdf4':'#fff'};opacity:${locked?0.5:1}">
        <div style="font-size:13px">${AMMO_TIER_ICONS[t-1]}</div>
        <div style="font-size:8px;color:#475569">×${mult[t-1].toFixed(1)}</div>
        <div style="font-size:9px;color:${locked?'#cbd5e1':(owned>0?'#15803d':'#94a3b8')};font-weight:600">${locked?('🔒'+AMMO_TIER_UNLOCK_LV[t-1]):owned}</div>
        <div style="font-size:8px;color:${enabled?'#16a34a':'#94a3b8'}">${locked?'':(enabled?T('เปิด'):T('ปิด'))}</div></div>`;
    }
    return `<div style="margin-top:6px"><div style="font-size:10px;color:#475569;margin-bottom:3px">${T('🗼 กระสุนป้อม — เปิดหลาย tier ได้ (ยิง T สูงสุดที่มีกระสุนก่อน หมดแล้วไล่ลง)')}</div>
      <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:4px">${cells}</div></div>`;
  }

  let skillTab = 'atk'; // แท็บสายสกิลที่เลือกอยู่ (atk/def/melee/turret)
  function renderSkills() {
    const el = document.getElementById('skill-list');
    if (!el) return;
    const skills = getSkills();
    const sp = player.skill_pts ?? 0;

    let html = `<div class="skill-sp-bar">
      <span class="skill-sp-label">⚡ Skill Point</span>
      <span><span class="skill-sp-val">${sp}</span><span class="skill-sp-label"> ${T('คงเหลือ')}</span></span>
    </div>`;

    const treeCounts = {}, treeInvest = {}; // นับสกิลในสาย + แต้มที่ลงแล้ว (โชว์ badge บน tab)
    SKILL_DEFS.forEach(d => { treeCounts[d.tree] = (treeCounts[d.tree] || 0) + 1; treeInvest[d.tree] = (treeInvest[d.tree] || 0) + (parseInt(skills[d.id] ?? 0)); });

    // ── แท็บ 4 สาย (ย่อเมนูที่ยาว) — เลือกสายเดียวแสดง ──
    const _trees = ['atk', 'def', 'melee', 'turret'];
    if (!_trees.includes(skillTab)) skillTab = 'atk';
    html += `<div style="display:flex;gap:4px;margin-bottom:8px">` + _trees.map(tr => {
      const t = SKILL_TREE_LABELS[tr], on = skillTab === tr;
      const _ic = t.label.split(' ')[0], _nm = (t.label.split('— ')[1] || tr);
      return `<button onclick="xhrpg.setSkillTab('${tr}')" style="flex:1;min-width:0;font-size:11px;padding:6px 2px;border:none;border-radius:8px;font-weight:700;cursor:pointer;line-height:1.25;${on?`background:${t.color}1f;color:${t.color};box-shadow:inset 0 0 0 2px ${t.color}`:'background:#f1f5f9;color:#64748b'}">${_ic} ${T(_nm)}<br><span style="font-size:8.5px;font-weight:600;opacity:.85">${T('{a}/{b} แต้ม', {a: treeInvest[tr]||0, b: treeCounts[tr]*10})}</span></button>`;
    }).join('') + `</div>`;

    let lastTree = null;
    SKILL_DEFS.filter(d => d.tree === skillTab).forEach((def, idx) => {
      if (def.tree !== lastTree) {
        if (lastTree !== null) html += `</div></div>`; // ปิด .skill-tree-cards + .skill-tree-panel ของสายก่อนหน้า
        const t = SKILL_TREE_LABELS[def.tree];
        html += `<div class="skill-tree-panel" style="border-color:${t.color}40">
          <div class="skill-tree-head" style="background:${t.color}14;border-left-color:${t.color}">
            <span class="skill-tree-head-label" style="color:${t.color}">${T(t.label)}</span>
            <span class="skill-tree-head-count" style="color:${t.color}">${T('{a} สกิล', {a: treeCounts[def.tree]})}</span>
          </div>
          <div class="skill-tree-cards">`;
        lastTree = def.tree;
      }

      const lv = (int => int)(parseInt(skills[def.id] ?? 0));
      const maxLv = def.maxLv;
      const isMax = lv >= maxLv;
      const unlocked = !def.req
        ? true
        : (def.req.all
            ? def.req.all.every(c => c.player_lv != null ? ((player.lv||1) >= c.player_lv) : (parseInt(skills[c.skill] ?? 0) >= c.lv))
            : (parseInt(skills[def.req.skill] ?? 0) >= def.req.lv));
      const tag = TYPE_TAG[def.type];
      const treeColor = SKILL_TREE_LABELS[def.tree].color;

      const dots = Array.from({length:maxLv},(_,i) =>
        `<div class="skill-dot" style="background:${i<lv?treeColor:'transparent'};border-color:${treeColor};opacity:${i<lv?1:0.25}"></div>`
      ).join('');

      const btnStyle = isMax
        ? `border-color:${treeColor};color:${treeColor};opacity:0.5`
        : unlocked && sp > 0
          ? `border-color:${treeColor};color:${treeColor}`
          : `border-color:var(--color-border-tertiary);color:var(--color-text-secondary)`;
      const btnText = !unlocked ? T('🔒 ล็อค') : isMax ? T('✓ เต็ม') : T('+ อัพ');
      const btnDisabled = (!unlocked || isMax || sp <= 0) ? 'disabled' : '';
      const btnOnclick = (!unlocked || isMax || sp <= 0) ? '' : `onclick="xhrpg.upgradeSkill('${def.id}')"`;

      // ── format เดียวกันทุกสกิล ──
      const reqText = !def.req
        ? T('ต้นสาย (ไม่มีเงื่อนไข)')
        : (def.req.all
            ? def.req.all.map(c => c.player_lv != null ? T('เลเวล {a}', {a: c.player_lv}) : `${T(SKILL_DEFS.find(d=>d.id===c.skill)?.name || c.skill)} Lv.${c.lv}`).join(' + ')
            : `${T(SKILL_DEFS.find(d=>d.id===def.req.skill)?.name || def.req.skill)} Lv.${def.req.lv}`);
      const _mut = '#94a3b8', _val = '#334155';
      const _chip = (lbl, v) => `<div><span style="color:${_mut}">${lbl}</span> <b style="color:${_val}">${v}</b></div>`;
      const gridHtml = [
        _chip('⚡ MP', def.mp > 0 ? def.mp : '—'),
        _chip('⏱ CD', def.cd),
        def.rng  ? _chip(T('🎯 ระยะ'), def.rng(lv)) : '',
        def.xtra ? _chip('ℹ️', def.xtra(lv))      : '',
      ].join('');

      html += `<div class="skill-card${!unlocked?' locked':''}${isMax?' maxed':''}" id="skc-${def.id}">
        <div class="skill-top">
          <div class="skill-ico">${def.id === 'deploy_turret' ? `<img src="${assetsBaseUrl}assets/hero/turret.png" alt="${def.icon}" style="width:17px;height:17px;image-rendering:pixelated;vertical-align:-2px" onerror="this.outerHTML=this.alt">` : def.icon}</div>
          <div class="skill-mid">
            <div class="skill-name">${T(def.name)}
              <span class="skill-tag" style="background:${tag.bg};color:${tag.color};border-color:${tag.border}">${tag.label}</span>
            </div>
          </div>
          <div class="skill-right">
            <div class="skill-lv" id="sk-lv-${def.id}">${isMax ? 'MAX' : `Lv. ${lv}/${maxLv}`}</div>
            <button class="skill-up-btn" style="${btnStyle}" ${btnDisabled} ${btnOnclick}>${btnText}</button>
            ${(def.type === 'active' || def.id === 'twin_turret') ? (() => {
              let sa = player.skill_auto;
              if (typeof sa === 'string') { try { sa = JSON.parse(sa); } catch(e) { sa = {}; } }
              if (!sa || typeof sa !== 'object') sa = {};
              const autoOn = (sa[def.id] ?? 1) ? true : false;
              return `<button class="skill-auto-toggle ${autoOn?'on':'off'}" onclick="xhrpg.toggleSkillAuto('${def.id}')">${autoOn?T('✓ เปิด'):T('✕ ปิด')}</button>`;
            })() : ''}</div>
        </div>
        <div class="skill-dots" id="sk-dots-${def.id}">${dots}</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 10px;font-size:12px;margin:7px 0 6px">${gridHtml}</div>
        <div style="background:${treeColor}0f;border-radius:8px;padding:6px 9px;font-size:12px;margin-bottom:5px">
          <div><span style="color:${_mut}">${T('📊 ตอนนี้')}</span> <b style="color:${treeColor}" id="sk-stat-${def.id}">${def.statLabel(lv)}</b></div>
          <div style="margin-top:2px"><span style="color:${_mut}">${T('⬆ ต่อ Lv')}</span> <span style="color:${_val}">${T(def.perLv)}</span></div>
        </div>
        <div style="font-size:11px;color:${unlocked ? _mut : '#dc2626'}">${T('🔓 ปลดล็อก:')} ${reqText}</div>
      </div>`;
    });
    if (lastTree !== null) html += `</div></div>`; // ปิดกล่องสายสุดท้าย

    el.innerHTML = _resIco(html);
  }

  function setSkillTab(tree) { skillTab = tree; renderSkills(); }
  function upgradeSkill(skillId) {
    if (!player) return;
    $.post(baseUrl + 'xhrpg_upgrade.php', { line_uid: player.line_uid, action: 'skill_up', skill_id: skillId })
      .done(res => {
        const d = typeof res === 'string' ? JSON.parse(res) : res;
        if (d.ok) {
          player = d.player;
          renderSkills();
          updateHUD();
          addLog([{type:'levelup', msg: d.msg}]);
        } else {
          addLog([{type:'default', msg: d.error || T('ไม่สามารถอัพสกิลได้')}]);
        }
      });
  }

  function toggleSkillAuto(skillId) {
    if (!player) return;
    $.post(baseUrl + 'xhrpg_upgrade.php', { line_uid: player.line_uid, action: 'skill_toggle', skill_id: skillId })
      .done(res => {
        const d = typeof res === 'string' ? JSON.parse(res) : res;
        if (d.ok) {
          player = d.player;
          renderSkills();
          addLog([{type:'default', msg: d.msg}]);
        } else {
          addLog([{type:'default', msg: d.error || T('ไม่สามารถเปลี่ยนสถานะสกิลได้')}]);
        }
      });
  }

  function useSkill(skillId) {
    if (!player) return;
    $.post(baseUrl + 'xhrpg_upgrade.php', { line_uid: player.line_uid, action: 'use_skill', skill_id: skillId })
      .done(res => {
        const d = typeof res === 'string' ? JSON.parse(res) : res;
        if (d.ok) {
          player = d.player;
          updateHUD();
          renderSkills();
          addLog([{type:'kill', msg: d.msg}]);
        } else {
          addLog([{type:'default', msg: d.error || T('ใช้สกิลไม่ได้')}]);
        }
      });
  }

