  // ══════════════════════════════════════════════════════════════════
  const MKT_RARITY_BASE = { white:40, green:90, blue:180, purple:350, gold:700, red:1200 };
  // (design A) ตลาดแบบ 3 แท็บ: buy (กริดกลุ่มสินค้า + drill-down) / my / history
  // วางขายไม่ใช่แท็บแล้ว — เป็น sheet 2 ขั้น เปิดจากปุ่มบน header
  let mktMode      = 'buy';  // 'buy' | 'my' | 'history'
  let mktSellOpen  = false;  // sheet วางขายเปิดอยู่หรือไม่ (ทับ body ของแท็บปัจจุบัน)
  let mktSellStep  = 1;      // 1=เลือกของ 2=ตั้งราคา/จำนวน
  let mktBuyStep   = 1;      // 1=กริดกลุ่ม/รายละเอียดกลุ่ม 2=ยืนยันซื้อ 3=ซื้อสำเร็จ
  let mktSellCat   = 'treasure';
  let mktBuyCat    = 'all';
  let mktSelItem   = null;
  let mktSelListing= null;
  let mktSelGroup  = null;   // drill-down: {kind:'item', key} (fungible) | {kind:'cat', cat} (unique)
  let mktModFilter = 'all';  // ฟิลเตอร์ชิ้นโมดูลใน drill-down: all|barrel|sight|rare|plus
  let mktBuySearch = '';
  let mktSellPrice = 1;
  let mktSellQty   = 1;
  let mktHistFilter= 'all';

  const MKT_RESOURCE_DEFS = [
    { field:'wood',   icon:'🪵', name:'ไม้',        desc:'วัตถุดิบสำหรับยานบิน' },
    { field:'stone',  icon:'🪨', name:'หิน',        desc:'วัตถุดิบสำหรับยานบิน' },
    { field:'iron',   icon:'🔩', name:'เหล็ก',      desc:'วัตถุดิบสำหรับอาวุธ/มีดสั้น' },
    { field:'copper', icon:'🟤', name:'ทองแดง',     desc:'วัตถุดิบสำหรับมีดสั้น' },
    { field:'herb',   icon:'🌿', name:'สมุนไพร',    desc:'วัตถุดิบสำหรับยา' },
  ];
  const MKT_DIAMOND_DEFS = [ // เพชรขายได้ (fungible เหมือน resource) · icon = emoji (item_icon ส่งขึ้น DB)
    { field:'diamond_blue',  icon:'💎', name:'เพชรฟ้า',  desc:'ตีบวกโมดูล (ทุกระดับ)',  rarity:'blue'  },
    { field:'diamond_red',   icon:'🔴', name:'เพชรแดง',  desc:'ตีบวกโมดูล +6 ขึ้นไป',   rarity:'red'   },
    { field:'diamond_green', icon:'🟢', name:'เพชรเขียว', desc:'ตีบวกโมดูล +12 ขึ้นไป',  rarity:'green' },
  ];
  const MKT_CATS = [
    { key:'resource',    label:'ทรัพยากร' },
    { key:'diamond',     label:'💎 เพชร' },
    { key:'ammo',        label:'🔫 กระสุน' },
    { key:'treasure',    label:'🗃️ ของวิเศษ ของล้ำค่า' },
    { key:'hardware',    label:'🗃️ ของวิเศษ ชิ้นส่วนไททัน' },
    { key:'weapon_parts',label:'🗃️ ของวิเศษ ชิ้นส่วนอาวุธ' },
    { key:'house_parts', label:'🗃️ ของวิเศษ ชิ้นส่วนยานบิน' },
    { key:'stat_parts',  label:'🗃️ ของวิเศษ ชิ้นส่วนสเตตัส' },
    { key:'equipment',   label:'🗃️ ของวิเศษ อุปกรณ์สวมใส่' },
    { key:'card',        label:'🎴 การ์ดมอน' },
    { key:'module_pistol', label:'🔪 โมดูลมีดสั้น' },
    { key:'module_sniper', label:'🗡️ โมดูลมีดยาว' },
    { key:'module_knife',  label:'🗡️ โมดูลดาบ' },
    { key:'module_axe',    label:'🪓 โมดูลขวาน' },
    { key:'module_robot',  label:'🔋 โมดูลไททัน' },
    { key:'module_robot_gun', label:'🦾 โมดูลธนูไททัน (ARM)' },
    { key:'module_railgun',   label:'⚡ โมดูล Premium Titan Beam' },
    { key:'module_armor',  label:'🛡️ โมดูลเกราะ' },
    { key:'module_house',  label:'🛸 โมดูลยานบิน' },
    { key:'module_turret', label:'🗼 โมดูลป้อม' },
    { key:'module_box',    label:'📦 กล่องสุ่มโมดูล' },
    { key:'card_box',      label:'🎁 กล่องสุ่มการ์ด' },
    { key:'egg',           label:'🥚 ไข่สัตว์เลี้ยง' },
  ];
  // override icon SVG เฉพาะแถวชิปหมวด (select/search ยังใช้ label emoji เดิม — SVG ใส่ใน <option> ไม่ได้)
  const _MKT_CAT_CHIP = { // ฟังก์ชัน — แปลตอนเรนเดอร์ (ไอคอนเป็น <img> ผสมข้อความ ใส่ T ทั้งก้อนไม่ได้)
    module_pistol: () => _LOG_KNIFE_S + ' ' + T('โมดูลมีดสั้น'),
    module_sniper: () => _LOG_KNIFE_B + ' ' + T('โมดูลมีดยาว'),
    module_knife:  () => _LOG_SWORD  + ' ' + T('โมดูลดาบ'),
    diamond: () => _icoGemHtml('blue',12) + _icoGemHtml('red',12) + _icoGemHtml('green',12) + ' ' + T('เพชร'),
  };
  // ราคาตั้งต้นแนะนำของโมดูล แยกตามระดับ rarity 1-7
  const MKT_MODULE_BASE = { 1:60, 2:150, 3:400, 4:900, 5:2000, 6:5000, 7:12000 };
  // ราคาตั้งต้นแนะนำของการ์ด (แค่ค่าเริ่มต้น ผู้ขายปรับเองได้)
  const MKT_CARD_BASE = { white:150, green:400, blue:900, purple:2000, gold:5000, red:12000 };
  // rarity การ์ดจากเลเวลมอน (MVP = ขยับขึ้น 1 ระดับ) — ใช้จัดสี/ราคาตั้งต้น
  function _cardRarity(lv, mvp) {
    lv = lv | 0;
    let r = lv <= 4 ? 'white' : lv <= 9 ? 'green' : lv <= 14 ? 'blue' : lv <= 19 ? 'purple' : 'gold';
    if (mvp) { const o = ['white','green','blue','purple','gold','red']; r = o[Math.min(o.length - 1, o.indexOf(r) + 1)]; }
    return r;
  }

  // master maps built from existing JS masters (already defined in the IIFE above)
  function _mktMasters() {
    return {
      treasure:     TREASURE_MASTER,
      hardware:     HARDWARE_MASTER,
      weapon_parts: WEAPON_PARTS_MASTER,
      house_parts:  HOUSE_PARTS_MASTER,
      stat_parts:   STAT_PARTS_MASTER,
    };
  }

  function _mktDecodeQty(v) {
    if (!v) return {};
    try { return typeof v === 'object' ? v : JSON.parse(v); } catch(e) { return {}; }
  }

  // Return sellable items for current player + category
  // จำนวนกระสุนที่มี ตาม gun+tier (mirror ของ PHP xhrpg_ammo_get)
  function _ammoOwned(gun, tier) {
    if (tier <= 1) { const k = 'ammo_' + (gun === 'robot' ? 'robot_gun' : gun); return parseInt(player[k]) || 0; }
    const f = 'ammo_' + (gun === 'robot' ? 'robot' : gun) + '_extra';
    const raw = player[f];
    let arr = Array.isArray(raw) ? raw : [];
    if (typeof raw === 'string') { try { arr = JSON.parse(raw||'[]')||[]; } catch(e){ arr=[]; } }
    return parseInt(arr[tier-2]) || 0;
  }

  function _mktInventory(cat) {
    if (!player) return [];
    if (cat === 'ammo') {
      const guns = [{g:'pistol',icon:'🔪',name:'มีดสั้น'},{g:'sniper',icon:'🗡️',name:'มีดยาว'},{g:'robot',icon:'🦾',name:'ลูกธนูไททัน'}]; // ชื่อ/icon โชว์ (key g คงเดิม) — emoji ล้วน กัน item_icon ยาวเกิน (เดิม img HTML)
      const tierIcons = ['⚪','🟢','🔵','🟣','🟡','🔴'];
      const rarByTier = ['white','green','blue','purple','gold','red'];
      const dmgMult   = [1.0,1.2,1.4,1.6,1.8,2.0];
      const sugg      = [5,12,25,45,75,120];
      const out = [];
      guns.forEach(gn => {
        for (let t = 1; t <= 6; t++) {
          const owned = _ammoOwned(gn.g, t);
          if (owned <= 0) continue;
          out.push({
            id: `ammo_${gn.g}_${t}`, item_type: 'ammo', item_id: 0,
            item_slot: gn.g, tier: t,
            icon: `${gn.icon}${tierIcons[t-1]}`,
            name: `${gn.name} ${tierIcons[t-1]} T${t}`,
            desc: `ดาเมจ ×${dmgMult[t-1].toFixed(1)}`,
            rarity: rarByTier[t-1], qty: owned, suggested: sugg[t-1],
          });
        }
      });
      return out;
    }
    if (cat === 'resource') {
      return MKT_RESOURCE_DEFS
        .filter(r => (player[r.field] || 0) > 0)
        .map(r => ({
          id: `resource_${r.field}`,
          item_type: 'resource',
          item_id: r.field,   // field name — used as resource key in PHP
          item_slot: r.field, // also stored in item_slot for buy/return path
          icon: r.icon, name: r.name, desc: r.desc,
          rarity: 'white', qty: player[r.field] || 0,
        }));
    }
    if (cat === 'diamond') {
      return MKT_DIAMOND_DEFS
        .filter(d => (player[d.field] || 0) > 0)
        .map(d => ({
          id: `diamond_${d.field}`, item_type: 'diamond',
          item_id: d.field, item_slot: d.field,
          icon: d.icon, name: d.name, desc: d.desc,
          rarity: d.rarity, qty: player[d.field] || 0,
        }));
    }
    if (cat === 'module_box') {
      // 📦 กล่องสุ่มโมดูล — stackable ต่อระดับ (tier → item_tier ฝั่ง server)
      const out = [];
      for (let t = 1; t <= 4; t++) {
        const n = player['module_box' + t] | 0; if (n <= 0) continue;
        const meta = MODULE_BOX_META[t - 1];
        out.push({
          id: 'module_box_' + t, item_type: 'module_box', item_id: 0, item_slot: '', tier: t,
          icon: '📦', name: `กล่องโมดูล${meta.n}`,
          desc: `เปิดสุ่มโมดูล rarity ${t + 1} (${t + 1} รู) ทุกอาวุธ`,
          rarity: ['blue', 'purple', 'gold', 'red'][t - 1], qty: n,
          suggested: MKT_MODULE_BASE[t + 1] || 150,
        });
      }
      return out;
    }
    if (cat === 'card_box') {
      // 🎁 กล่องสุ่มการ์ด — stackable ต่อระดับ 1-8
      const rar = ['white', 'green', 'blue', 'purple', 'gold', 'red', 'red', 'red'];
      const out = [];
      for (let t = 1; t <= 8; t++) {
        const n = player['card_box' + t] | 0; if (n <= 0) continue;
        const lo = (t - 1) * 10 + 1, hi = t * 10;
        out.push({
          id: 'card_box_' + t, item_type: 'card_box', item_id: 0, item_slot: '', tier: t,
          icon: '🎁', name: `กล่องการ์ด Lv.${lo}-${hi}`,
          desc: `สุ่มการ์ดมอน Lv.${lo}-${hi} · ⭐MVP 1%`,
          rarity: rar[t - 1], qty: n,
          suggested: MKT_CARD_BASE[rar[t - 1]] || 150,
        });
      }
      return out;
    }
    if (cat === 'egg') {
      // 🥚 ไข่สัตว์เลี้ยง — โครงเดียวกับการ์ด (ต่อมอน × ปกติ/MVP)
      const eggs = _eggsArr();
      const out = [];
      Object.keys(eggs).forEach(mid => {
        const mm = monMasters[mid]; if (!mm) return;
        const own = eggs[mid] || {};
        [['n', false], ['m', true]].forEach(([k, mvp]) => {
          const cnt = own[k] | 0; if (cnt <= 0) return;
          const hatchCost = (mm.lv || 1) * 100 * (mvp ? 10 : 1);
          out.push({
            id: `egg_${k}_${mid}`, item_type: 'egg', item_id: +mid,
            item_slot: mvp ? 'mvp' : 'normal',
            icon: '🥚', name: `ไข่${mm.n || '?'}${mvp ? ' ⭐MVP' : ''}`,
            desc: `สัตว์เลี้ยง Lv.${mm.lv || 1} · ค่าฟัก ${hatchCost.toLocaleString()} G`,
            rarity: _cardRarity(mm.lv || 1, mvp), qty: cnt,
            suggested: Math.max(100, (mm.lv || 1) * (mvp ? 5000 : 500)),
          });
        });
      });
      return out;
    }
    if (cat === 'module_pistol' || cat === 'module_sniper' || cat === 'module_knife' || cat === 'module_axe' || cat === 'module_robot' || cat === 'module_robot_gun' || cat === 'module_railgun' || cat === 'module_armor' || cat === 'module_house' || cat === 'module_turret') {
      const wk = cat.slice(7); // pistol / sniper / knife / axe / robot / armor / house / turret
      const invField = _MOD_INV_FIELD[wk] || 'module_inventory';
      const inv = Array.isArray(player[invField]) ? player[invField] : (JSON.parse(player[invField]||'[]')||[]);
      const wIcon = wk==='sniper' ? '🗡️' : wk==='knife' ? '🔪' : wk==='axe' ? '🪓' : wk==='robot' ? '🔋' : wk==='armor' ? '🛡️' : wk==='house' ? '🛸' : wk==='turret' ? '🗼' : '🔪'; // emoji ล้วน — กัน item_name ยาวเกิน (เดิม pistol/sniper ใส่ img HTML ~230 ตัวอักษร → ล้นคอลัมน์ item_name)
      const wWord = wk==='sniper' ? 'มีดยาว' : wk==='knife' ? 'มีด' : wk==='axe' ? 'ขวาน' : wk==='robot' ? 'ไททัน' : wk==='armor' ? 'เกราะ' : wk==='house' ? 'ยานบิน' : wk==='turret' ? 'ป้อม' : 'มีดสั้น';
      return inv.map((m,i) => ({ m, i }))
        .sort((a,b) => (b.m.rarity - a.m.rarity) || ((b.m.plus||0) - (a.m.plus||0)))
        .map(({ m, i }) => {
        const sn  = _modSlotName(wk, m.slot);
        const ico = _modSlotIcon(wk, m.slot);
        const stat= _modEffectShort(wk, m);
        const stTxt = m.stat ? ` · ${_modStatLabel(m.stat)} +${m.rarity}` : '';
        const rarN = (MODULE_RARITY[m.rarity-1]||MODULE_RARITY[0]).n;
        return {
          id: `${cat}_${i}`, item_type:cat,
          item_id: i, item_slot: m.slot,
          icon: ico, name: `${wIcon} ${sn} ${rarN} +${m.plus}`, desc: `${wWord} · ${stat}${stTxt}`,
          rarity: m.rarity, qty: 1, module: m, isModule: true,
        };
      });
    }
    if (cat === 'card') {
      const cards = (player.cards && typeof player.cards === 'object' && !Array.isArray(player.cards)) ? player.cards
                  : (() => { try { return JSON.parse(player.cards || '{}') || {}; } catch (e) { return {}; } })();
      const out = [];
      Object.keys(cards).forEach(mid => {
        const mm = monMasters[mid]; if (!mm) return;
        const own = cards[mid] || {};
        [['n', false], ['m', true]].forEach(([k, mvp]) => {
          const cnt = own[k] | 0; if (cnt <= 0) return;
          const st = (mm.cs || '').toLowerCase();
          out.push({
            id: `card_${k}_${mid}`, item_type: 'card', item_id: +mid,
            item_slot: mvp ? 'mvp' : 'normal',
            icon: mm.e || '🎴', name: `${mm.n || '?'}${mvp ? ' ⭐MVP' : ''}`,
            desc: `การ์ด · +${_cardValue(mm.lv || 1, mvp)} ${_CARD_STAT_LBL[st] || '?'}`,
            rarity: _cardRarity(mm.lv || 1, mvp), qty: cnt,
          });
        });
      });
      return out;
    }
    const masters = _mktMasters();
    if (cat === 'equipment') {
      const eqOwned = _mktDecodeQty(player.equipment);
      const eqQty   = player._equipmentQty || _mktDecodeQty(player.equipment_qty);
      const eqMaster= player._equipmentMaster || {};
      const items = [];
      ['head','body','hand','foot','ring','necklace'].forEach(slot => {
        const def   = eqMaster[slot]; if (!def) return;
        const tiers = Array.isArray(eqOwned[slot]) ? eqOwned[slot] : [];
        tiers.forEach(tier => {
          const tDef   = def.tiers[tier]; if (!tDef) return;
          const dupQty = (eqQty[slot] && typeof eqQty[slot]==='object') ? (parseInt(eqQty[slot][tier])||0) : 0;
          const sellQty= dupQty + 1; // 1 base + extras
          // can only sell duplicates (qty > 1 means we have extras to sell while keeping 1)
          if (sellQty < 1) return;
          items.push({
            id: `eq_${slot}_${tier}`, slot, tier,
            icon: tDef.icon, name: tDef.name, desc: def.label + ' ' + (def.stat === 'intel' ? 'INT' : def.stat.toUpperCase()) + '+' + tier,
            rarity: tDef.rarity, qty: sellQty,
            item_type:'equipment', item_id:0,
          });
        });
      });
      return items;
    }
    const master = masters[cat] || [];
    const listField = { treasure:'treasures', hardware:'hardware', weapon_parts:'weapon_parts', house_parts:'house_parts', stat_parts:'stat_parts' }[cat];
    const qtyField  = listField + '_qty';
    const owned     = (() => { const v=player[listField]; return Array.isArray(v)?v:(typeof v==='string'?JSON.parse(v||'[]'):[]); })();
    const qtyMap    = _mktDecodeQty(player[qtyField]);
    return master
      .filter(m => owned.includes(m.id))
      .map(m => ({
        id: `${cat}_${m.id}`, item_id: m.id,
        icon: m.icon, name: m.name, desc: m.desc, rarity: m.rarity||'white',
        qty: (parseInt(qtyMap[m.id])||0) + 1,
        item_type: cat,
      }));
  }

  function _mktRarityClass(r) {
    return 'mkt-r-' + (r||'white');
  }

  function renderMarket() {
    const root = document.getElementById('market-root');
    if (!root) return;
    root.innerHTML = _mktBuildRoot();
    _mktBindEvents();
  }

  // (design A) header: ชิปทอง · ช่องค้นหา · ปุ่มวางขาย + แถบแท็บ 3 ชิป
  function _mktBuildRoot() {
    const goldVal = (player?.gold||0).toLocaleString();
    return `
      <div class="mkt2-head">
        <div class="mkt2-gold" id="mkt2-gold">${_icoHtml('💰')} ${goldVal}</div>
        <input class="mkt2-search" type="text" placeholder="${T('🔍 ค้นหา...')}" value="${mktBuySearch}" oninput="xhrpg._mktBuySearch(this.value)">
        <button class="mkt2-sellbtn" onclick="xhrpg._mktOpenSell()">${T('🏷️ + วางขาย')}</button>
      </div>
      <div class="mkt2-tabs">
        <button class="mkt2-tab ${mktMode==='buy'?'on':''}" data-mode="buy" onclick="xhrpg._mktSetMode('buy')">${T('🛒 ซื้อ')}</button>
        <button class="mkt2-tab ${mktMode==='my'?'on':''}" data-mode="my" onclick="xhrpg._mktSetMode('my')">${T('📦 ของฉัน')}<span class="mkt2-badge" id="mkt2-my-badge" style="display:none"></span></button>
        <button class="mkt2-tab ${mktMode==='history'?'on':''}" data-mode="history" onclick="xhrpg._mktSetMode('history')">${T('🧾 ประวัติ')}</button>
      </div>
      <div id="mkt-body">${_mktBody()}</div>`;
  }

  function _mktSetMode(m) {
    if (m === 'sell') { _mktOpenSell(); return; } // ชื่อเดิม (back-compat) — วางขายกลายเป็น sheet แล้ว
    mktMode = m;
    mktSellOpen = false;
    if (m==='buy')     { mktBuyStep=1; mktSelListing=null; mktSelGroup=null; window._mktListingsCache=null; }
    if (m==='my')      { window._mktMyCache=null; }
    if (m==='history') { window._mktHistCache=null; mktHistFilter='all'; }
    document.querySelectorAll('.mkt2-tab').forEach(b => b.classList.toggle('on', b.dataset.mode === m));
    _mktRefreshBody();
    _mktBindEvents();
  }

  function _mktRefreshBody() {
    const b = document.getElementById('mkt-body');
    if (b) b.innerHTML = _mktBody();
  }

  function _mktBody() {
    if (mktSellOpen)         return _mktSellSheet();
    if (mktMode==='history') return _mktHistoryBody();
    if (mktMode==='my')      return _mktMyBody();
    return _mktBuyBody();
  }

  // dropdown หมวด จัดกลุ่ม 3 กลุ่ม (ใช้ใน sheet วางขาย)
  function _mktCatSelect(active, setter, withAll) {
    const groups = [
      { label:null,         keys:['resource','diamond','ammo'] },
      { label:'🗃️ ของวิเศษ', keys:['treasure','hardware','weapon_parts','house_parts','stat_parts','equipment','card'] },
      { label:'🔧 โมดูล',    keys:['module_pistol','module_sniper','module_knife','module_axe','module_robot','module_robot_gun','module_railgun','module_armor','module_house','module_turret'] },
      { label:'🎁 กล่อง/ไข่', keys:['module_box','card_box','egg'] }, // 📦🎁🥚 กล่องสุ่ม + ไข่สัตว์เลี้ยง
    ];
    const byKey = Object.fromEntries(MKT_CATS.map(c => [c.key, c]));
    let opts = withAll ? `<option value="all" ${active==='all'?'selected':''}>${T('ทั้งหมด')}</option>` : '';
    groups.forEach(g => {
      const inner = g.keys.filter(k=>byKey[k]).map(k => { const c=byKey[k];
        return `<option value="${c.key}" ${c.key===active?'selected':''} ${c.locked?'disabled':''}>${T(c.label)}${c.locked?' 🔒':''}</option>`;
      }).join('');
      opts += g.label ? `<optgroup label="${T(g.label)}">${inner}</optgroup>` : inner;
    });
    return `<select class="mkt-cat-sel" onchange="xhrpg.${setter}(this.value)">${opts}</select>`;
  }
  function _mktSellNormalCard(it) {
    return `<div class="mkt-icard ${_mktRarityClass(it.rarity)} ${mktSelItem?.id===it.id?'sel':''}" onclick="xhrpg._mktPickItem('${it.id}')">
      <span class="ico">${_icoHtml(it.icon, 16)}</span><div class="nm">${_mktTName(it.name)}</div><div class="qt">×${it.qty}</div></div>`;
  }
  // แถบการ์ดที่เสียบในโมดูล (โชว์ตอนขาย/ซื้อโมดูล — การ์ดติดไปกับโมดูล)
  // รวม combat bonus จากการ์ด MVP ที่เสียบในโมดูลที่สวมอยู่ (mirror xhrpg_module_card_combat_bonus ฝั่ง PHP)
  const _CB_LBL = { str:'STR', agi:'AGI', vit:'VIT', dex:'DEX', intel:'INT', luk:'LUK', atk:'ATK', armor:'เกราะ', hp:'HP', mp:'MP', hp_regen:'HP/s', mp_regen:'MP/s' };
  // ✨ โบนัสสะสม (mirror xhrpg_collection_cb): ต่อชนิด ปกติ n>0=+1 · MVP m>0=+3 · การ์ด+ไข่ → +ATK/DEF/HP/MP
  function _collCBof(o) { o=(o&&typeof o==='object'&&!Array.isArray(o))?o:(()=>{try{return JSON.parse(o||'{}')||{};}catch(e){return {};}})(); let b=0; for(const k in o){const v=o[k]; if(v&&((v.n|0)>0))b+=1; if(v&&((v.m|0)>0))b+=3;} return b; }
  function _collCB() { return _collCBof(player&&player.cards) + _collCBof(player&&player.eggs); }
  function _cardCB() {
    const out = { atk:0, range:0, armor:0, hp:0, mp:0 };
    if (!player) return out;
    const _coll = _collCB(); if (_coll > 0) { out.atk += _coll; out.hp += _coll; out.mp += _coll; } // ✨ โบนัสสะสม → ATK/HP/MP (DEF โชว์แยก)
    ['pistol_modules','sniper_modules','knife_modules','axe_modules','robot_modules','robot_gun_modules','railgun_modules','armor_modules','house_modules','turret_modules'].forEach(f => {
      if (f === 'railgun_modules' && (+(player.robot_railgun_expires || 0)) <= Math.floor(Date.now()/1000)) return;
      let mods = player[f];
      if (typeof mods === 'string') { try { mods = JSON.parse(mods || '{}'); } catch (e) { mods = {}; } }
      if (!mods || typeof mods !== 'object') return;
      Object.keys(mods).forEach(k => {
        const m = mods[k];
        if (!m || !Array.isArray(m.cards)) return;
        m.cards.forEach(c => {
          if (!c || !c.mvp || !c.mb) return;
          const t = c.mb.t, a = c.mb.a | 0;
          if (a > 0 && out[t] !== undefined) out[t] += a;
        });
      });
    });
    return out;
  }
  function _modCardsBadge(cards) {
    if (!Array.isArray(cards) || !cards.length) return '';
    const txt = cards.map(c => {
      let s = `${c.mvp?'⭐':''}+${c.v|0} ${_CARD_STAT_LBL[(c.s||'').toLowerCase()]||'?'}`;
      if (c.mb && (c.mb.a|0) > 0) s += ` +${c.mb.a|0}${_CB_LBL[c.mb.t]||c.mb.t}`;
      return s;
    }).join(' · ');
    return `<div style="font-size:9px;font-weight:700;color:#dc2626;margin-top:1px" title="การ์ดที่เสียบในโมดูล (ติดไปกับโมดูล · MVP มีโบนัสคอมแบต)">🎴 ${txt}</div>`;
  }
  function _mktModuleCard(it) {
    const m = it.module, rar = MODULE_RARITY[m.rarity-1]||MODULE_RARITY[0];
    const sel = mktSelItem?.id===it.id ? 'box-shadow:0 0 0 2px #2563eb;' : '';
    const valTxt = (it.item_slot==='barrel'||it.item_slot==='mag') ? `ATK +${_modBarrelAtk(m)}` : `+${(_modPoints(m)*0.30).toFixed(1)}m`;
    const stTxt  = m.stat ? `${_modStatLabel(m.stat)} +${m.rarity}` : '';
    return `<button onclick="xhrpg._mktPickItem('${it.id}')" style="text-align:left;background:#fff;border:1px solid #e7e5e4;border-left:3px solid ${rar.c};border-radius:0 8px 8px 0;padding:6px 7px;cursor:pointer;${sel}">
      <div style="display:flex;align-items:center"><span style="font-size:13px">${it.icon}</span><span style="margin-left:auto;font-size:10px;font-weight:700;color:${m.plus>0?'#7c3aed':'#78716c'}">+${m.plus}</span></div>
      <span style="font-size:8px;color:#fff;${_rarBg(m.rarity)};border-radius:3px;padding:0 5px;display:inline-block;margin-top:2px">${T(rar.n)}</span>
      <div style="font-size:10px;font-weight:600;color:#16a34a;margin-top:2px">${valTxt}</div>
      <div style="font-size:9px;font-weight:600;color:#7c3aed;min-height:11px">${stTxt}</div>
      ${_modCardsBadge(m.cards)}
    </button>`;
  }
  function _mktModuleLegend() {
    return '<div class="mkt-legend"><span class="mkt-lg-t">' + T('ระดับโมดูล') + '</span>' +
      MODULE_RARITY.map((r,i) => `<span class="mkt-lg"><i style="${i===6?'background:linear-gradient(90deg,#f87171,#fbbf24,#34d399,#60a5fa,#a78bfa)':'background:'+r.c}"></i>${T(r.n)}</span>`).join('') +
      '</div>';
  }

  // ── SELL SHEET (design A: 2 ขั้น แทน wizard 4 ขั้นเดิม — ตรรกะ/validation เดิมทั้งหมด) ──
  function _mktOpenSell()  { mktSellOpen = true; mktSellStep = 1; mktSelItem = null; _mktRefreshBody(); }
  function _mktCloseSell() { mktSellOpen = false; mktSelItem = null; _mktRefreshBody(); _mktBindEvents(); }

  function _mktSellSheet() {
    return `<div class="mkt2-sheet">` + (mktSellStep === 2 ? _mktSellStep2() : _mktSellStep1()) + `</div>`;
  }

  function _mktSheetHead(title, backFn) {
    return `<div class="mkt2-shead">
      <button class="mkt2-back" onclick="xhrpg.${backFn}()">‹</button>
      <div class="mkt2-stitle">${title}</div>
      <button class="mkt2-x" onclick="xhrpg._mktCloseSell()">✕</button>
    </div>`;
  }

  // ขั้น 1: เลือกหมวด (dropdown เดิม) + กริดของจากกระเป๋า (การ์ดเดิม)
  function _mktSellStep1() {
    const isMod = mktSellCat.indexOf('module_') === 0 && mktSellCat !== 'module_box'; // module_box = กล่อง stackable ไม่ใช่โมดูลรายชิ้น (ใช้ grid/legend แบบการ์ดปกติ)
    const items = _mktInventory(mktSellCat);
    const cards = items.length
      ? items.map(it => it.isModule ? _mktModuleCard(it) : _mktSellNormalCard(it)).join('')
      : '<div class="mkt-empty" style="grid-column:1/-1"><div class="ei">📭</div><div class="et">' + T('ยังไม่มีของในหมวดนี้') + '</div><div class="ed">' + T('ลองเลือกหมวดอื่น หรือออกไปเก็บของเพิ่ม') + '</div></div>';
    const grid = `<div class="${isMod?'mkt-mod-grid':'mkt-inv-grid'}">${cards}</div>`;
    return _mktSheetHead(T('🏷️ วางขาย — เลือกของ'), '_mktCloseSell') +
      '<div class="mkt-catbar">' + _mktCatSelect(mktSellCat, '_mktSetSellCat', false) + '</div>' +
      grid +
      (isMod ? _mktModuleLegend() : _mktRarityLegend());
  }

  // 🌐 แปลชื่อของใน listing (item_name จาก DB เป็นไทย) — ชื่อประกอบแบบ "มีดสั้น ⚪ T3" คีย์ตรงไม่ match → แยก suffix tier ออก แปลฐาน แล้วต่อกลับ
  function _mktTName(n) {
    n = String(n || '');
    const t = T(n);
    if (t !== n || LANG() === 'th') return t; // dict ตรง หรือโหมดไทย = จบ
    const m = n.match(/^(.*?)(\s*(?:[⚪🟢🔵🟣🟡🔴]\s*)?T\d+)$/u); // "ชื่อฐาน [ไอคอน] T3"
    return m ? T(m[1].trim()) + m[2] : n;
  }
  function _mktRarityLegend() {
    const r = [['#6b7280','ขาว'],['#22c55e','เขียว'],['#3b82f6','ฟ้า'],['#a855f7','ม่วง'],['#eab308','ทอง'],['#ef4444','แดง']];
    return '<div class="mkt-legend"><span class="mkt-lg-t">' + T('ความหายาก') + '</span>' +
      r.map(([c,n]) => `<span class="mkt-lg"><i style="background:${c}"></i>${T(n)}</span>`).join('') +
      '</div>';
  }

  // คีย์ระบุ "ของชนิดเดียวกัน" — mirror วิธีเก็บฝั่ง PHP (item_id ถูก cast เป็น int, resource ใช้ item_slot)
  function _mktItemKey(type, id, slot, tier) { return type + '|' + (parseInt(id)||0) + '|' + (slot||'') + '|' + (parseInt(tier)||0); }
  function _mktListingKey(l) { return _mktItemKey(l.item_type, l.item_id, l.item_slot, l.item_tier); }
  function _mktModPayload(l) { try { const p = JSON.parse(l.item_payload||'null'); return (p && typeof p==='object') ? p : null; } catch(e) { return null; } }

  // ราคา/ชิ้นต่ำสุดของ "ของชิ้นเดียวกัน" ที่ขายอยู่ในตลาด — null ถ้าไม่มี (ใช้เป็น hint ตอนตั้งราคา)
  function _mktMarketMinFor(it) {
    const cached = window._mktListingsCache;
    if (!cached || !cached.length) return null;
    const now = Math.floor(Date.now()/1000);
    let match;
    if (it.isModule) {
      // โมดูล: เทียบหมวด + ช่อง + ระดับ rarity เดียวกัน (ชิ้นต่อชิ้นไม่ซ้ำกันอยู่แล้ว)
      match = l => {
        if (l.item_type !== it.item_type) return false;
        const p = _mktModPayload(l);
        return !!p && p.slot === it.module.slot && (parseInt(p.rarity)||1) === (parseInt(it.module.rarity)||1);
      };
    } else {
      const key = _mktItemKey(it.item_type, it.item_id, it.item_slot||it.slot||'', it.tier||0);
      match = l => _mktListingKey(l) === key;
    }
    const prices = cached.filter(l => parseInt(l.expires_at) >= now && match(l))
      .map(l => parseInt(l.price_per)).filter(n => n > 0);
    return prices.length ? Math.min(...prices) : null;
  }

  // ขั้น 2: จำนวน (×10 / MAX) + ราคา/ชิ้น + hint ราคาตลาด + สุทธิหลัง fee + แถบยืนยันเขียว
  function _mktSellStep2() {
    if (!mktSelItem) return _mktSellStep1();
    const it   = mktSelItem;
    const minP = _mktMarketMinFor(it);
    const net0 = (mktSellPrice - Math.ceil(mktSellPrice*0.05)) * mktSellQty;
    const qtyRow = it.qty > 1
      ? `<div class="mkt-frow"><label>${T('จำนวน')}</label><input type="number" id="mkt-qty" value="${mktSellQty}" min="1" max="${it.qty}" oninput="xhrpg._mktCalcNet()">
          <button class="mkt2-qbtn" onclick="xhrpg._mktQtySell('x10')">×10</button>
          <button class="mkt2-qbtn" onclick="xhrpg._mktQtySell('max')">MAX</button>
          <span style="font-size:11px;color:#4b5563;white-space:nowrap">/ ${it.qty}</span></div>`
      : '';
    return _mktSheetHead(T('🏷️ วางขาย — ตั้งราคา'), '_mktSellBack') +
      `<div class="mkt-detail"><div class="dico">${it.isModule ? it.icon : _icoHtml(it.icon, 20)}</div><div><div class="dname">${_mktTName(it.name)}</div><div class="ddesc">${T(it.desc)}</div></div></div>` + // โมดูลคงไอคอนช่องเดิม (📏/🎯/⚙️ ฯลฯ) — กันชนกับ map เหล็ก
      qtyRow +
      `<div class="mkt-frow"><label>${T('ราคา/ชิ้น')}</label><input type="number" id="mkt-price" value="${mktSellPrice}" min="1" oninput="xhrpg._mktCalcNet()"><span style="font-size:13px;color:#4b5563">G</span></div>` +
      (minP != null ? `<div class="mkt2-mhint">${T('💡 ราคาตลาดตอนนี้: เริ่ม {a}G', {a: minP.toLocaleString()})}</div>` : '') +
      `<div class="mkt-net">${T('รับสุทธิ (หัก fee 5%): ')}<strong id="mkt-net-val">${net0.toLocaleString()} G</strong></div>` +
      `<div class="mkt-note">${T('สินค้าจะหมดอายุใน 24 ชม. — กด "ยกเลิก" ในแท็บของฉันเพื่อรับของคืน')}</div>` +
      `<button class="mkt2-confirm" onclick="xhrpg._mktDoSell()">${T('🏷️ วางขายเลย')}</button>`;
  }
  function _mktSellBack() { mktSelItem = null; mktSellStep = 1; _mktRefreshBody(); }

  // ปุ่มลัดจำนวนขาย: ×10 / MAX
  function _mktQtySell(mode) {
    const el = document.getElementById('mkt-qty'); if (!el) return;
    const max = parseInt(el.max)||1, cur = parseInt(el.value)||1;
    el.value = mode === 'max' ? max : Math.min(max, cur*10);
    _mktCalcNet();
  }

  // ── BUY (design A: กริดการ์ดกลุ่ม 3 คอลัมน์ + drill-down + ยืนยันซื้อ) ──
  const MKT_FUNGIBLE = { resource:1, diamond:1, ammo:1 }; // 📦🎁🥚 กล่อง/ไข่ ย้ายไป unique display (การ์ด grid สวยแบบโมดูล) — ยังซื้อทีละหลายชิ้นได้ (qty ในหน้ายืนยัน)

  function _mktBuyBody() {
    if (mktBuyStep===2) return _mktBuyConfirm();
    if (mktBuyStep===3) return _mktBuyDone();
    if (mktSelGroup)    return _mktGroupDetail();
    return _mktCatChips() + `<div class="mkt2-grid" id="mkt2-grid">${_mktGroupGrid()}</div>`;
  }

  // listings ที่ซื้อได้ (ตัดของตัวเอง + ของหมดอายุ) — เงื่อนไขเดิมของหน้าซื้อ
  function _mktBuyable() {
    const now = Math.floor(Date.now()/1000);
    return (window._mktListingsCache||[]).filter(l =>
      l.seller_uid !== player?.line_uid && parseInt(l.expires_at) >= now);
  }

  // แถวชิปหมวด (เลื่อนแนวนอน): ทั้งหมด + หมวดตาม MKT_CATS — หมวด locked หรี่ + 🔒 กดไม่ได้
  function _mktCatChips() {
    const chip = (key, label, locked) => locked
      ? `<span class="mkt2-chip lock" title="ยังไม่เปิดให้บริการ">${label} 🔒</span>`
      : `<span class="mkt2-chip ${mktBuyCat===key?'on':''}" onclick="xhrpg._mktSetBuyCat('${key}')">${label}</span>`;
    return `<div class="mkt2-chips">` + chip('all',T('ทั้งหมด'),false) +
      MKT_CATS.map(c => chip(c.key, _MKT_CAT_CHIP[c.key] ? _MKT_CAT_CHIP[c.key]() : T(c.label), !!c.locked)).join('') + `</div>`;
  }

  // จัดกลุ่ม fungible (resource/ammo): การ์ดต่อ "ชนิดของ" — N ประกาศ + ราคาเริ่ม
  function _mktGroupsFungible() {
    const map = {};
    _mktBuyable().forEach(l => {
      if (!MKT_FUNGIBLE[l.item_type]) return;
      const k = _mktListingKey(l);
      const g = map[k] || (map[k] = { key:k, cat:l.item_type, icon:l.item_icon, name:l.item_name, count:0, min:Infinity });
      g.count++;
      g.min = Math.min(g.min, parseInt(l.price_per)||0);
    });
    return Object.values(map);
  }

  // จัดกลุ่ม unique (ของสะสม + โมดูล): สรุปต่อ "หมวด" — N ชิ้น + ช่วงราคา
  function _mktGroupsUnique() {
    const by = {};
    _mktBuyable().forEach(l => {
      if (MKT_FUNGIBLE[l.item_type]) return;
      const g = by[l.item_type] || (by[l.item_type] = { pieces:0, min:Infinity, max:0, names:[] });
      g.pieces += parseInt(l.qty)||1;
      const p = parseInt(l.price_per)||0;
      g.min = Math.min(g.min, p); g.max = Math.max(g.max, p);
      g.names.push((l.item_name||'').toLowerCase());
    });
    return by;
  }

  // แยกไอคอนนำหน้า label หมวด (ใช้ทำไอคอนการ์ดหมวด)
  // ⚠️ บางหมวดใช้ไอคอนรูป (_LOG_KNIFE_S/B = แท็ก <img> ที่มีช่องว่างใน style) → ห้าม split(' ') ทั้งดุ้น
  //    ไม่งั้น icon=<img (แท็กพัง) + แอตทริบิวต์ที่เหลือโผล่เป็นข้อความดิบในการ์ด — แยกทั้งแท็ก <img> ก่อน
  function _mktCatIconLabel(c) {
    const lbl = T(c.label || ''); // แปลก่อนแยกไอคอน (EN คง emoji นำหน้า → split เดิมใช้ได้)
    const im = lbl.match(/^(<img\b[^>]*>)\s*(.*)$/i);
    if (im) return { icon: im[1], label: im[2] };
    const sp = lbl.split(' ');
    return sp.length > 1 ? { icon: sp[0], label: sp.slice(1).join(' ') } : { icon: '🗃️', label: lbl };
  }

  // กริดการ์ดกลุ่ม 3 คอลัมน์ (กรองด้วยชิปหมวด + ช่องค้นหาบน header)
  function _mktGroupGrid() {
    if (window._mktListingsCache == null) return `<div class="mkt2-loading">${T('กำลังโหลด...')}</div>`;
    const q = mktBuySearch;
    const catOrder = {}; MKT_CATS.forEach((c,i) => { catOrder[c.key] = i; });
    let cards = '';
    // fungible: การ์ดต่อชนิดของ — ของที่ไม่มีประกาศไม่แสดง
    _mktGroupsFungible()
      .filter(g => mktBuyCat==='all' || mktBuyCat===g.cat)
      .filter(g => !q || (g.name||'').toLowerCase().includes(q))
      .sort((a,b) => (catOrder[a.cat]-catOrder[b.cat]) || (a.name<b.name?-1:1))
      .forEach(g => {
        cards += `<div class="mkt2-gcard" onclick="xhrpg._mktPickGroup('${g.key}')">
          <div class="gi">${_icoHtml(g.icon, 16)}</div><div class="gn">${_mktTName(g.name)}</div>
          <div class="gm">${T('{a} ประกาศ', {a: g.count})}</div><div class="gp">${T('เริ่ม {a}G', {a: g.min.toLocaleString()})}</div></div>`;
      });
    // unique: การ์ดต่อหมวด — หมวดว่างแสดงการ์ดหรี่ "—"
    const uniq = _mktGroupsUnique();
    MKT_CATS.filter(c => !MKT_FUNGIBLE[c.key] && !c.locked)
      .filter(c => mktBuyCat==='all' || mktBuyCat===c.key)
      .filter(c => !q || c.label.toLowerCase().includes(q) || (uniq[c.key] ? uniq[c.key].names.some(n => n.includes(q)) : false))
      .forEach(c => {
        const g  = uniq[c.key];
        const il = _mktCatIconLabel(c);
        if (!g) {
          cards += `<div class="mkt2-gcard dim"><div class="gi">${_icoHtml(il.icon, 16)}</div><div class="gn">${il.label}</div><div class="gm">${T('{a} ชิ้น', {a: 0})}</div><div class="gp">—</div></div>`;
          return;
        }
        const price = g.min===g.max ? `${g.min.toLocaleString()}G` : `${g.min.toLocaleString()}–${g.max.toLocaleString()}G`;
        cards += `<div class="mkt2-gcard" onclick="xhrpg._mktPickGroup('${c.key}')">
          <div class="gi">${_icoHtml(il.icon, 16)}</div><div class="gn">${il.label}</div>
          <div class="gm">${T('{a} ชิ้น', {a: g.pieces})}</div><div class="gp">${price}</div></div>`;
      });
    return cards || `<div class="mkt2-loading">${T('ไม่พบสินค้า')}</div>`;
  }

  // แตะการ์ดกลุ่ม → สลับ body เป็นหน้ารายละเอียด (มีปุ่มกลับ)
  function _mktPickGroup(key) {
    mktSelGroup = key.indexOf('|') >= 0 ? { kind:'item', key } : { kind:'cat', cat:key };
    mktModFilter = 'all';
    _mktRefreshBody();
  }
  function _mktGroupBack() { mktSelGroup = null; mktSelListing = null; mktBuyStep = 1; _mktRefreshBody(); }
  function _mktSetModFilter(f) { mktModFilter = f; _mktRefreshBody(); }

  function _mktGroupDetail() {
    if (!mktSelGroup) return '';
    return mktSelGroup.kind === 'item' ? _mktFungibleDetail(mktSelGroup.key) : _mktCatDetail(mktSelGroup.cat);
  }

  function _mktDetHead(title) {
    return `<div class="mkt2-dethead"><button class="mkt2-back" onclick="xhrpg._mktGroupBack()">${T('‹ กลับ')}</button><span class="ti">${title}</span></div>`;
  }

  // drill-down fungible: แถวเรียงราคา/ชิ้นถูกสุดก่อน — ×qty · ราคา/ชิ้น · ผู้ขาย · [ซื้อ]
  function _mktFungibleDetail(key) {
    const rows = _mktBuyable().filter(l => _mktListingKey(l) === key)
      .sort((a,b) => (parseInt(a.price_per)||0) - (parseInt(b.price_per)||0));
    const first = rows[0];
    const head  = _mktDetHead(first ? `${_icoHtml(first.item_icon, 16)} ${_mktTName(first.item_name)}` : T('สินค้า'));
    if (!rows.length) return head + `<div class="mkt2-loading">${T('ไม่มีประกาศขายแล้ว')}</div>`;
    return head + `<div class="mkt2-rows">` + rows.map(l => `
      <div class="mkt2-lrow">
        <span class="q">×${parseInt(l.qty).toLocaleString()}</span>
        <span class="p">${parseInt(l.price_per).toLocaleString()}G<span class="pu">${T('/ชิ้น')}</span></span>
        <span class="s">${l.seller_name}</span>
        <button class="mkt2-buybtn" onclick="xhrpg._mktPickListing(${l.id})">${T('ซื้อ')}</button>
      </div>`).join('') + `</div>`;
  }

  // หมวดโมดูลที่มีช่อง barrel/sight (ใช้ตัดสินว่าจะโชว์ชิปกรองช่องไหม)
  const MKT_MOD_SLOT_CATS = { module_pistol:1, module_sniper:1, module_knife:1, module_axe:1, module_robot_gun:1, module_railgun:1 };

  // drill-down unique: โมดูล → การ์ดรายชิ้น + ชิปกรอง / ของสะสม → แถวชื่อ+ราคา
  function _mktCatDetail(cat) {
    const cdef  = MKT_CATS.find(c => c.key === cat);
    const isMod = cat.indexOf('module_') === 0 && cat !== 'module_box'; // module_box = กล่อง ไม่ใช่โมดูลรายชิ้น (ไม่โชว์ชิปกรองช่อง/ตีบวก)
    let rows = _mktBuyable().filter(l => l.item_type === cat);
    const head = _mktDetHead(cdef ? T(cdef.label) : cat);
    let chips = '';
    if (isMod) {
      const wk = cat.slice(7);
      const defs = [{ f:'all', t:T('ทั้งหมด') }];
      if (MKT_MOD_SLOT_CATS[cat]) defs.push({ f:'barrel', t:T(_modSlotName(wk,'barrel')) }, { f:'sight', t:T(_modSlotName(wk,'sight')) }, { f:'mag', t:T(_modSlotName(wk,'mag')) });
      defs.push({ f:'rare', t:T('หายาก+') }, { f:'plus', t:T('มีตีบวก') });
      chips = `<div class="mkt2-chips" style="margin:2px 0 8px">` + defs.map(d =>
        `<span class="mkt2-chip ${mktModFilter===d.f?'on':''}" onclick="xhrpg._mktSetModFilter('${d.f}')">${d.t}</span>`).join('') + `</div>`;
      rows = rows.filter(l => {
        if (mktModFilter === 'all') return true;
        const p = _mktModPayload(l) || {};
        if (mktModFilter === 'barrel') return p.slot === 'barrel';
        if (mktModFilter === 'mag')    return p.slot === 'mag';
        if (mktModFilter === 'sight')  return p.slot === 'sight';
        if (mktModFilter === 'rare')   return (parseInt(p.rarity)||parseInt(l.item_rarity)||1) >= 3;
        if (mktModFilter === 'plus')   return (parseInt(p.plus)||0) > 0;
        return true;
      });
    }
    rows.sort((a,b) => (parseInt(a.price_per)||0) - (parseInt(b.price_per)||0));
    if (cat === 'egg') rows.sort((a,b) => { // 🥚 MVP ก่อน · Lv สูง→ต่ำ · ราคาถูกสุดก่อน (tie)
      const A = _mktEggMeta(a), B = _mktEggMeta(b);
      return (B.mvp - A.mvp) || (B.lv - A.lv) || ((parseInt(a.price_per)||0) - (parseInt(b.price_per)||0));
    });
    if (!rows.length) return head + chips + `<div class="mkt2-loading">${T('ไม่มีประกาศในหมวดนี้')}</div>`;
    const isCard = cat === 'card';
    const isBox  = cat === 'module_box' || cat === 'card_box';
    const isEgg  = cat === 'egg';
    const cardFn = isCard ? _mktCardPieceCard : isBox ? _mktBoxPieceCard : isEgg ? _mktEggPieceCard : _mktModPieceCard;
    const body = (isMod || isCard || isBox || isEgg)
      ? `<div class="mkt2-mgrid">` + rows.map(cardFn).join('') + `</div>`
      : `<div class="mkt2-mgrid">` + rows.map(_mktUniquePieceCard).join('') + `</div>`;
    return head + chips + body;
  }

  // การ์ดโมดูลรายชิ้นฝั่งซื้อ — วิชวลเดียวกับการ์ดคลัง (_mktModuleCard) + ราคา/ผู้ขาย/ปุ่มซื้อ
  function _mktModPieceCard(l) {
    const p   = _mktModPayload(l) || {};
    const r   = parseInt(p.rarity) || parseInt(l.item_rarity) || 1;
    const rar = MODULE_RARITY[r-1] || MODULE_RARITY[0];
    const wk  = p.weapon || (l.item_type||'').slice(7);
    const m   = { slot: p.slot||'barrel', rarity: r, plus: parseInt(p.plus)||0, stat: p.stat||null };
    const stTxt = m.stat ? `${_modStatLabel(m.stat)} +${m.rarity}` : '';
    return `<div class="mkt2-mcard" style="border-left:3px solid ${rar.c}">
      <div style="display:flex;align-items:center"><span style="font-size:13px">${l.item_icon}</span><span style="margin-left:auto;font-size:10px;font-weight:700;color:${m.plus>0?'#7c3aed':'#78716c'}">+${m.plus}</span></div>
      <span style="font-size:8px;color:#fff;${_rarBg(r)};border-radius:3px;padding:0 5px;display:inline-block;margin-top:2px">${T(rar.n)}</span>
      <div style="font-size:10px;font-weight:600;color:#16a34a;margin-top:2px">${_modEffectShort(wk, m)}</div>
      <div style="font-size:9px;font-weight:600;color:#7c3aed;min-height:11px">${stTxt}</div>
      ${_modCardsBadge(p.cards)}
      <div class="mprice">${parseInt(l.price_per).toLocaleString()}G</div>
      <div class="mseller">${l.seller_name}</div>
      <button class="mkt2-buybtn w" onclick="xhrpg._mktPickListing(${l.id})">${T('ซื้อ')}</button>
    </div>`;
  }

  // การ์ดฝั่งซื้อ — การ์ด grid สวย (วิชวลเดียวกับโมดูล): icon + Lv/⭐MVP + ชื่อ + ค่าพลัง + ราคา/ผู้ขาย/ปุ่มซื้อ · แสดงผลอย่างเดียว
  const _CARD_RAR_C = { white:'#94a3b8', green:'#22c55e', blue:'#3b82f6', purple:'#a855f7', gold:'#f59e0b', red:'#dc2626' };
  function _mktCardPieceCard(l) {
    let pl = null; try { pl = typeof l.item_payload === 'object' ? l.item_payload : JSON.parse(l.item_payload || 'null'); } catch (e) {}
    const mid = (pl && pl.mid) ? pl.mid : l.item_id;
    const mvp = (pl && pl.mvp) || l.item_slot === 'mvp';
    const mm  = monMasters[mid] || {};
    const st  = (mm.cs || '').toLowerCase();
    const clr = _CARD_STAT_CLR[st] || '#94a3b8';
    const su  = _CARD_STAT_LBL[st] || '?';
    const lv  = mm.lv || 1;
    const v   = _cardValue(lv, mvp);
    const bc  = _CARD_RAR_C[_cardRarity(lv, mvp)] || '#94a3b8';
    const mb  = mvp ? _mvpCardBonus(+mid, lv) : null;
    const mbTxt = (mb && mb.a > 0) ? `+${mb.a} ${_CB_LBL[mb.t]||mb.t}` : '';
    return `<div class="mkt2-mcard" style="border-left:3px solid ${bc}">
      <div style="display:flex;align-items:center"><span style="font-size:16px">${l.item_icon}</span><span style="margin-left:auto;font-size:8px;font-weight:800;color:#fff;background:${mvp?'#dc2626':bc};padding:0 4px;border-radius:4px">${mvp?'⭐MVP':'Lv.'+lv}</span></div>
      <div style="font-size:10px;font-weight:600;color:#111;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${T(mm.n || l.item_name || '?')}</div>
      <div style="font-size:11px;font-weight:700;color:${clr};margin-top:1px">+${v} ${su}</div>
      <div style="font-size:9px;font-weight:600;color:#7c3aed;min-height:11px">${mbTxt}</div>
      ${(()=>{ const _q=parseInt(l.qty)||1; return _q>1 ? `<div style="font-size:10px;font-weight:800;color:#b45309">×${_q.toLocaleString()} ${T('ใบ')}</div>` : ''; })()}
      <div class="mprice">${parseInt(l.price_per).toLocaleString()}G<span style="font-size:8px;color:#94a3b8;font-weight:400">${(parseInt(l.qty)||1)>1?T('/ใบ'):''}</span></div>
      <div class="mseller">${l.seller_name}</div>
      <button class="mkt2-buybtn w" onclick="xhrpg._mktPickListing(${l.id})">${T('ซื้อ')}</button>
    </div>`;
  }

  // การ์ดกล่องสุ่มฝั่งซื้อ (โมดูล/การ์ด) — grid สวยแบบโมดูล: icon + ระดับ + คำอธิบายสิ่งที่ได้ + ×qty + ราคา/ผู้ขาย/ปุ่มซื้อ
  function _mktBoxPieceCard(l) {
    const isCardBox = l.item_type === 'card_box';
    const t   = parseInt(l.item_tier) || 1;
    const c   = isCardBox ? (CARD_BOX_COLORS[t-1] || '#94a3b8') : ((MODULE_BOX_META[t-1]||{}).c || '#94a3b8');
    const name = isCardBox ? T('กล่องการ์ด Lv.{a}-{b}', {a: (t-1)*10+1, b: t*10}) : T('กล่องโมดูล{a}', {a: T((MODULE_BOX_META[t-1]||{}).n||'')});
    const sub  = isCardBox ? T('สุ่มการ์ดมอน Lv.{a}-{b} · ⭐MVP 1%', {a: (t-1)*10+1, b: t*10}) : T('สุ่มโมดูล rarity {a} ({b} รู) ทุกอาวุธ', {a: t+1, b: t+1});
    const qty  = parseInt(l.qty) || 1;
    return `<div class="mkt2-mcard" style="border-left:3px solid ${c}">
      <div style="display:flex;align-items:center"><span style="font-size:16px">${isCardBox?'🎁':'📦'}</span><span style="margin-left:auto;font-size:8px;font-weight:800;color:#fff;background:${c};padding:0 4px;border-radius:4px">${T('ระดับ {a}', {a: t})}</span></div>
      <div style="font-size:10px;font-weight:600;color:#111;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${name}</div>
      <div style="font-size:9px;color:#64748b;margin-top:1px;min-height:22px;line-height:1.3">${sub}</div>
      <div style="font-size:9px;font-weight:700;color:#7c3aed;min-height:11px">${qty>1?T('มี ×{a} ใบ', {a: qty}):''}</div>
      <div class="mprice">${parseInt(l.price_per).toLocaleString()}G</div>
      <div class="mseller">${l.seller_name}</div>
      <button class="mkt2-buybtn w" onclick="xhrpg._mktPickListing(${l.id})">${T('ซื้อ')}</button>
    </div>`;
  }
  // การ์ดไข่สัตว์เลี้ยงฝั่งซื้อ — grid สวยแบบการ์ด: 🥚 + Lv/⭐MVP + ชื่อมอน + ค่าฟัก + ×qty + ราคา/ผู้ขาย/ปุ่มซื้อ
  function _mktEggMeta(l) { // ดึง {lv, mvp} จากประกาศไข่ (สำหรับเรียงลำดับ)
    let pl = null; try { pl = typeof l.item_payload === 'object' ? l.item_payload : JSON.parse(l.item_payload || 'null'); } catch (e) {}
    const mid = (pl && pl.mid) ? pl.mid : l.item_id;
    const mvp = ((pl && pl.mvp) || l.item_slot === 'mvp') ? 1 : 0;
    const lv  = (monMasters[mid] || {}).lv || (pl && pl.lv) || 1;
    return { lv, mvp };
  }
  function _mktEggPieceCard(l) {
    let pl = null; try { pl = typeof l.item_payload === 'object' ? l.item_payload : JSON.parse(l.item_payload || 'null'); } catch (e) {}
    const mid = (pl && pl.mid) ? pl.mid : l.item_id;
    const mvp = (pl && pl.mvp) || l.item_slot === 'mvp';
    const mm  = monMasters[mid] || {};
    const lv  = mm.lv || (pl && pl.lv) || 1;
    const bc  = _CARD_RAR_C[_cardRarity(lv, mvp)] || '#94a3b8';
    const hatch = lv * 100 * (mvp ? 10 : 1);
    const qty = parseInt(l.qty) || 1;
    return `<div class="mkt2-mcard" style="border-left:3px solid ${bc}">
      <div style="display:flex;align-items:center"><span style="font-size:16px">🥚</span><span style="margin-left:auto;font-size:8px;font-weight:800;color:#fff;background:${mvp?'#dc2626':bc};padding:0 4px;border-radius:4px">${mvp?'⭐MVP':'Lv.'+lv}</span></div>
      <div style="font-size:10px;font-weight:600;color:#111;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${T(mm.n || l.item_name || 'ไข่')}</div>
      <div style="font-size:9px;color:#64748b;margin-top:1px;min-height:22px;line-height:1.3">${T('ฟักเป็นสัตว์เลี้ยง')}</div>
      <div style="font-size:9px;font-weight:700;color:#7c3aed;min-height:11px">${qty>1?T('มี ×{a} ฟอง', {a: qty}):''}</div>
      <div class="mprice">${parseInt(l.price_per).toLocaleString()}G</div>
      <div class="mseller">${l.seller_name}</div>
      <button class="mkt2-buybtn w" onclick="xhrpg._mktPickListing(${l.id})">${T('ซื้อ')}</button>
    </div>`;
  }
  // แถวของสะสม unique (ไม่ใช่โมดูล/การ์ด): ชื่อ + ราคา + ผู้ขาย + [ซื้อ]
  // การ์ดของวิเศษฝั่งซื้อ (ชิ้นส่วนสเตตัส/ไททัน/อาวุธ/ยานบิน/ของล้ำค่า/อุปกรณ์) — grid สวยแบบโมดูล: icon + สีระดับ + ชื่อ + ผล(item_desc) + ราคา/ผู้ขาย/ปุ่มซื้อ
  const _SPEC_RAR_TH = { white:'ขาว', green:'เขียว', blue:'ฟ้า', purple:'ม่วง', gold:'ทอง', red:'แดง' };
  function _mktUniquePieceCard(l) {
    const c   = _CARD_RAR_C[l.item_rarity] || '#94a3b8';
    const qty = parseInt(l.qty) || 1;
    const rl  = _SPEC_RAR_TH[l.item_rarity] || '';
    return `<div class="mkt2-mcard" style="border-left:3px solid ${c}">
      <div style="display:flex;align-items:center"><span style="font-size:16px">${_icoHtml(l.item_icon, 16)}</span>${rl?`<span style="margin-left:auto;font-size:8px;font-weight:800;color:#fff;background:${c};padding:0 4px;border-radius:4px">${T(rl)}</span>`:''}</div>
      <div style="font-size:10px;font-weight:600;color:#111;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${_mktTName(l.item_name)}</div>
      <div style="font-size:9px;color:#16a34a;font-weight:600;margin-top:1px;min-height:22px;line-height:1.3;overflow:hidden">${l.item_desc || ''}</div>
      <div style="font-size:9px;font-weight:700;color:#7c3aed;min-height:11px">${qty>1?`×${qty}`:''}</div>
      <div class="mprice">${parseInt(l.price_per).toLocaleString()}G</div>
      <div class="mseller">${l.seller_name}</div>
      <button class="mkt2-buybtn w" onclick="xhrpg._mktPickListing(${l.id})">${T('ซื้อ')}</button>
    </div>`;
  }

  function _mktPlayerOwns(l) {
    if (!player) return false;
    if (l.item_type === 'resource' || l.item_type === 'diamond') return false; // stackable, always can buy more
    if (l.item_type === 'module_box' || l.item_type === 'card_box') return ((player[l.item_type + (parseInt(l.item_tier)||0)] | 0) > 0);
    if (l.item_type === 'egg') {
      const eggs = _eggsArr();
      let pl = null; try { pl = typeof l.item_payload === 'object' ? l.item_payload : JSON.parse(l.item_payload || 'null'); } catch (e) {}
      const mid = (pl && pl.mid) ? pl.mid : l.item_id;
      const mvp = (pl && pl.mvp) || l.item_slot === 'mvp';
      const own = eggs[mid] || {};
      return ((mvp ? own.m : own.n) | 0) > 0;
    }
    if (l.item_type === 'card') {
      const cards = _mktDecodeQty(player.cards);
      let pl = null; try { pl = typeof l.item_payload === 'object' ? l.item_payload : JSON.parse(l.item_payload || 'null'); } catch (e) {}
      const mid = (pl && pl.mid) ? pl.mid : l.item_id;
      const mvp = (pl && pl.mvp) || l.item_slot === 'mvp';
      const own = cards[mid] || {};
      return ((mvp ? own.m : own.n) | 0) > 0;
    }
    if (l.item_type === 'equipment') {
      const eq = _mktDecodeQty(player.equipment);
      const tiers = Array.isArray(eq[l.item_slot]) ? eq[l.item_slot] : [];
      return tiers.some(t => t == l.item_tier);
    }
    const listField = { treasure:'treasures', hardware:'hardware', weapon_parts:'weapon_parts', house_parts:'house_parts', stat_parts:'stat_parts' }[l.item_type];
    if (!listField) return false;
    const owned = (() => { const v=player[listField]; return Array.isArray(v)?v:(typeof v==='string'?JSON.parse(v||'[]'):[]); })();
    return owned.some(id => id == l.item_id);
  }

  function _mktModInvCount(weapon) {
    const f = weapon==='module_sniper' ? 'sniper_module_inventory' : (weapon==='module_knife' ? 'knife_module_inventory' : (weapon==='module_axe' ? 'axe_module_inventory' : (weapon==='module_robot' ? 'robot_module_inventory' : (weapon==='module_armor' ? 'armor_module_inventory' : (weapon==='module_house' ? 'house_module_inventory' : (weapon==='module_robot_gun' ? 'robot_gun_module_inventory' : (weapon==='module_railgun' ? 'railgun_module_inventory' : (weapon==='module_turret' ? 'turret_module_inventory' : 'module_inventory'))))))));
    const v = player && player[f];
    const arr = Array.isArray(v) ? v : (typeof v==='string' ? (JSON.parse(v||'[]')||[]) : []);
    return arr.length;
  }

  // ยืนยันซื้อ — เงื่อนไข/ยอดรวมเดิม (_mktCalcBuyTotal/_mktDoBuy) + ปุ่มจำนวน +10/MAX
  // (backend รองรับซื้อบางส่วน: action=buy ส่ง qty ได้ ≤ qty ของ listing)
  function _mktBuyConfirm() {
    if (!mktSelListing) { mktBuyStep = 1; return _mktBuyBody(); }
    const l    = mktSelListing;
    const myG  = player?.gold || 0;
    const cost = parseInt(l.price_per);
    const ok   = myG >= cost;
    const isMod = (l.item_type||'').indexOf('module_') === 0 && l.item_type !== 'module_box'; // module_box = กล่อง ไม่เช็คคลังโมดูลเต็ม
    const invFull = isMod && _mktModInvCount(l.item_type) >= 30;
    const isNew = l.item_type !== 'resource' && l.item_type !== 'diamond' && !isMod && !_mktPlayerOwns(l);
    const banner = isMod
      ? (invFull
          ? `<div class="mkt-banner-new" style="background:#fee2e2;border-color:#fca5a5;color:#dc2626">${T('⚠️ คลังโมดูลเต็ม (30) — ทำลาย/ติดตั้งก่อนซื้อ')}</div>`
          : `<div class="mkt-banner-dup">${T('🔧 โมดูลรายชิ้น — จะเข้าคลังโมดูลของคุณ')}</div>`)
      : (l.item_type === 'resource' || l.item_type === 'diamond')
      ? `<div class="mkt-banner-dup">${l.item_type==='diamond'?T('💎 เพชร — จะเพิ่มเข้าคลังของคุณ'):T('📦 ทรัพยากร — จะเพิ่มเข้าคลังของคุณ')}</div>`
      : (isNew ? `<div class="mkt-banner-new">${T('✨ ของชิ้นนี้คุณยังไม่มี — ซื้อแล้วจะได้เป็นของใหม่!')}</div>` : `<div class="mkt-banner-dup">${T('📦 คุณมีของชิ้นนี้อยู่แล้ว — จะเพิ่มจำนวน')}</div>`);
    const qtyRow = parseInt(l.qty) > 1
      ? `<div class="mkt-crow"><span>${T('จำนวน')}</span><span class="cv"><input type="number" id="mkt-buy-qty" value="1" min="1" max="${l.qty}" style="width:52px;text-align:right;border:1px solid #d1d5db;border-radius:4px;padding:2px 4px" oninput="xhrpg._mktCalcBuyTotal()"> <button class="mkt2-qbtn" onclick="xhrpg._mktQtyBuy('add10')">+10</button> <button class="mkt2-qbtn" onclick="xhrpg._mktQtyBuy('max')">MAX</button> / ${l.qty}</span></div>`
      : `<div class="mkt-crow"><span>${T('จำนวน')}</span><span class="cv">${T('{a} ชิ้น', {a: 1})}</span></div>`;
    return `<div class="mkt2-dethead"><button class="mkt2-back" onclick="xhrpg._mktBuyGo(1)">${T('‹ กลับ')}</button><span class="ti">${T('ยืนยันการซื้อ')}</span></div>` +
      `<div class="mkt-detail"><div class="dico">${_icoHtml(l.item_icon, 20)}</div><div><div class="dname">${_mktTName(l.item_name)}</div><div class="ddesc">${T(l.item_desc)}</div><div style="font-size:11px;color:#4b5563;margin-top:3px">${T('ขายโดย {a}', {a: l.seller_name})}</div></div></div>` +
      banner +
      `<div class="mkt-crows">
        <div class="mkt-crow"><span>${T('ราคา')}</span><span class="cv">${T('{a} G / ชิ้น', {a: cost.toLocaleString()})}</span></div>
        ${qtyRow}
        <div class="mkt-crow"><span>${T('ทองที่มี')}</span><span class="cv">${myG.toLocaleString()} G</span></div>
        <div class="mkt-crow"><span>${T('รวม')}</span><span class="cv" id="mkt-buy-total">${cost.toLocaleString()} G</span></div>
        <div class="mkt-crow"><span>${T('คงเหลือหลังซื้อ')}</span><span class="cv ${ok?'cg':'cr'}" id="mkt-buy-remain">${(myG-cost).toLocaleString()} G</span></div>
      </div>` +
      (!ok ? '<div style="font-size:12px;color:#dc2626;margin-bottom:8px">' + T('ทองไม่พอ') + '</div>' : '') +
      `<button class="mkt2-confirm buy" onclick="xhrpg._mktDoBuy()" style="${(ok && !invFull)?'':'opacity:.4;pointer-events:none'}">${T('🛒 ซื้อเลย')}</button>`;
  }

  // ปุ่มลัดจำนวนซื้อ: +10 / MAX
  function _mktQtyBuy(mode) {
    const el = document.getElementById('mkt-buy-qty'); if (!el) return;
    const max = parseInt(el.max)||1, cur = parseInt(el.value)||1;
    el.value = mode === 'max' ? max : Math.min(max, cur+10);
    _mktCalcBuyTotal();
  }

  function _mktBuyDone() {
    if (!mktSelListing) { mktBuyStep = 1; return _mktBuyBody(); }
    const l = mktSelListing;
    return `<div class="mkt-big-ok"><div class="oi">🎉</div><div class="ot">${T('ซื้อสำเร็จ!')}</div><div class="od">${T('{a} จาก {b}', {a: _mktTName(l.item_name), b: l.seller_name})}</div></div>` +
      `<div class="mkt-recv"><div class="rico">${_icoHtml(l.item_icon, 20)}</div><div><div class="rname">${_mktTName(l.item_name)}</div><div class="rdesc">${T(l.item_desc)}</div><span class="mkt-badge-ok">${T('เข้ากระเป๋าแล้ว')}</span></div></div>` +
      `<button class="stat-btn" onclick="xhrpg._mktBuyGo(1)" style="width:100%;background:#eff6ff;color:#1d4ed8;border-color:#93c5fd">${T('ซื้อต่อ')}</button>`;
  }

  // ── MY LISTINGS (การ์ด grid สวยแบบหน้าซื้อ/ขาย · คง flow ยกเลิกเดิม _mktCancel) ───────────────────
  function _mktMyBody() {
    if (window._mktMyCache == null) return `<div id="mkt-my-rows"><div class="mkt-hload">${T('กำลังโหลด...')}</div></div>`;
    const now    = Math.floor(Date.now()/1000);
    const active = (window._mktMyCache||[]).filter(l => parseInt(l.expires_at) > now);
    if (!active.length) return `<div id="mkt-my-rows"><div class="mkt-empty"><div class="ei">📭</div><div class="et">${T('ไม่มีสินค้าที่วางขายอยู่')}</div></div></div>`;
    const cards = active.map(l => {
      const c   = _CARD_RAR_C[l.item_rarity] || '#cbd5e1';               // สีขอบตามความหายาก (ถ้ารู้)
      const hrs = Math.max(0, Math.round((parseInt(l.expires_at) - now) / 3600));
      return `<div class="mkt2-mcard" style="border-left:3px solid ${c}">
        <div style="display:flex;align-items:center"><span style="font-size:16px">${_icoHtml(l.item_icon, 16)}</span><span style="margin-left:auto;font-size:8px;font-weight:700;color:#64748b;background:#f1f5f9;padding:0 4px;border-radius:4px">${T('เหลือ {a} ชม.', {a: hrs})}</span></div>
        <div style="font-size:10px;font-weight:600;color:#111;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${_mktTName(l.item_name)}</div>
        <div style="font-size:9px;color:#64748b;margin-top:1px;min-height:22px;line-height:1.3;overflow:hidden">${l.item_desc || ''}</div>
        <div style="font-size:9px;font-weight:700;color:#7c3aed;min-height:11px">×${parseInt(l.qty).toLocaleString()}</div>
        <div class="mprice">${parseInt(l.price_per).toLocaleString()}G<span style="font-size:8px;color:#94a3b8">${T('/ชิ้น')}</span></div>
        <button class="mkt2-buybtn w" style="background:#fee2e2;color:#dc2626" onclick="xhrpg._mktCancel(${l.id})">${T('ยกเลิก')}</button>
      </div>`;
    }).join('');
    return `<div id="mkt-my-rows" class="mkt2-mgrid">${cards}</div>`;
  }

  // badge จำนวนประกาศ active บนแท็บ "ของฉัน" (จุดแดง+เลข — ซ่อนเมื่อไม่มี)
  function _mktUpdateMyBadge() {
    const el = document.getElementById('mkt2-my-badge');
    if (!el) return;
    const now = Math.floor(Date.now()/1000);
    const n = (window._mktMyCache||[]).filter(l => parseInt(l.expires_at) > now).length;
    el.style.display = n > 0 ? '' : 'none';
    el.textContent = n;
  }

  // ── action helpers ────────────────────────────────────────────────
  function _mktSetSellCat(cat) {
    mktSellCat = cat; mktSelItem = null; mktSellStep = 1;
    _mktRefreshBody();
  }
  // sheet วางขายมี 2 ขั้น (ชื่อเดิมคงไว้ — onclick เก่าเรียก _mktSellGo(2) ตอนเลือกของ)
  function _mktSellGo(n) {
    mktSellStep = Math.max(1, Math.min(2, n));
    _mktRefreshBody();
  }
  function _mktBuyGo(n)  { mktBuyStep  = n; _mktRefreshBody(); }
  function _mktSetBuyCat(cat) {
    mktBuyCat = cat; mktSelGroup = null; mktSelListing = null; mktBuyStep = 1;
    _mktRefreshBody();
  }
  // ค้นหาบน header — กรองการ์ดกลุ่มสด ๆ ฝั่ง client (ถ้า drill-down อยู่จะถอยกลับมาหน้ากริดก่อน)
  function _mktBuySearch(q) {
    mktBuySearch = q.toLowerCase();
    if (mktMode !== 'buy' || mktSellOpen) return;
    const g = document.getElementById('mkt2-grid');
    if (g && !mktSelGroup && mktBuyStep === 1) { g.innerHTML = _mktGroupGrid(); return; }
    mktSelGroup = null; mktSelListing = null; mktBuyStep = 1;
    _mktRefreshBody();
  }

  function _mktPickItem(id) {
    const all = MKT_CATS.flatMap(c => _mktInventory(c.key));
    mktSelItem = all.find(i => i.id === id);
    if (mktSelItem) {
      const resPrices = { wood:3, stone:5, iron:12, copper:15, herb:8, diamond_blue:50, diamond_red:200, diamond_green:500 };
      mktSellPrice = mktSelItem.isModule
        ? (MKT_MODULE_BASE[mktSelItem.module.rarity] || 100)
        : mktSelItem.item_type === 'card'
          ? (MKT_CARD_BASE[mktSelItem.rarity] || 150)
        : (mktSelItem.item_type === 'ammo' || mktSelItem.item_type === 'module_box' || mktSelItem.item_type === 'card_box' || mktSelItem.item_type === 'egg')
          ? (mktSelItem.suggested || 5)
        : (mktSelItem.item_type === 'resource' || mktSelItem.item_type === 'diamond')
          ? (resPrices[mktSelItem.item_id] || 5)
          : (MKT_RARITY_BASE[mktSelItem.rarity] || 50);
      mktSellQty   = 1;
      _mktSellGo(2);
    }
  }
  function _mktPickListing(id) {
    mktSelListing = (window._mktListingsCache||[]).find(l => l.id == id);
    if (mktSelListing) _mktBuyGo(2);
  }

  function _mktCalcNet() {
    mktSellPrice = parseInt(document.getElementById('mkt-price')?.value||mktSellPrice) || 1;
    mktSellQty   = parseInt(document.getElementById('mkt-qty')?.value||1) || 1;
    const net    = Math.round((mktSellPrice - Math.ceil(mktSellPrice*0.05)) * mktSellQty);
    const el     = document.getElementById('mkt-net-val');
    if (el) el.textContent = net.toLocaleString() + ' G' + (mktSellQty>1?' (×'+mktSellQty+')':'');
  }

  function _mktDoSell() {
    if (!mktSelItem || !player) return;
    _mktCalcNet(); // sync ราคา/จำนวนจาก input (ปุ่มยืนยันอยู่หน้าเดียวกับ input ใน sheet 2 ขั้น)
    const it    = mktSelItem;
    const price = mktSellPrice;
    const qty   = mktSellQty;
    const data  = {
      line_uid: player.line_uid, action:'sell',
      item_type: it.item_type, item_id: it.item_id||0,
      item_slot: it.item_slot||it.slot||'', item_tier: it.tier||0,
      item_icon: it.icon, item_name: it.name, item_desc: it.desc, item_rarity: it.rarity,
      qty, price_per: price,
    };
    if (it.isModule) {
      data.qty = 1;
      data.item_payload = JSON.stringify({ slot: it.module.slot, rarity: it.module.rarity, plus: it.module.plus||0, stat: it.module.stat||null, weapon: it.item_type==='module_sniper'?'sniper':(it.item_type==='module_knife'?'knife':(it.item_type==='module_axe'?'axe':(it.item_type==='module_robot'?'robot':(it.item_type==='module_armor'?'armor':(it.item_type==='module_house'?'house':(it.item_type==='module_robot_gun'?'robot_gun':(it.item_type==='module_railgun'?'railgun':(it.item_type==='module_turret'?'turret':'pistol')))))))) });
    }
    clearTimeout(pollTimer);
    $.post(baseUrl + 'xhrpg_market.php', data)
      .done(res => {
        const d = typeof res==='string'?JSON.parse(res):res;
        if (d.ok) {
          player = d.player;
          mktSellOpen = false; mktSelItem = null; mktSellStep = 1;
          window._mktMyCache = null; // ให้ badge/แท็บของฉัน refresh รายการใหม่
          _mktRefreshBody();
          _mktBindEvents();
          renderItems();
          const g = document.getElementById('mkt2-gold');
          if (g) g.innerHTML = _icoHtml('💰') + ' ' + (player.gold||0).toLocaleString(); // innerHTML: เนื้อหาเป็นตัวเลขจากเกม — ปลอดภัย
          addLog([{type:'default', msg:'🏷️ ' + (d.msg||T('วางขายสำเร็จ'))}]);
        } else {
          alert(T('เกิดข้อผิดพลาด: ') + (d.error||'unknown'));
        }
      })
      .always(() => schedulePoll()); // chain เดียวเสมอ — ถ้ามี poll ค้างอยู่ .always ของ poll นั้นจะตั้งรอบถัดไปเอง
  }

  function _mktCalcBuyTotal() {
    if (!mktSelListing || !player) return;
    const qty  = parseInt(document.getElementById('mkt-buy-qty')?.value || 1) || 1;
    const cost = parseInt(mktSelListing.price_per) * qty;
    const myG  = player.gold || 0;
    const elT  = document.getElementById('mkt-buy-total');
    const elR  = document.getElementById('mkt-buy-remain');
    if (elT) elT.textContent = cost.toLocaleString() + ' G';
    if (elR) { elR.textContent = (myG - cost).toLocaleString() + ' G'; elR.className = 'cv ' + (myG >= cost ? 'cg' : 'cr'); }
  }
  function _mktDoBuy() {
    if (!mktSelListing || !player) return;
    const l = mktSelListing;
    const qty = Math.max(1, Math.min(parseInt(l.qty), parseInt(document.getElementById('mkt-buy-qty')?.value || 1) || 1));
    clearTimeout(pollTimer);
    $.post(baseUrl + 'xhrpg_market.php', { line_uid: player.line_uid, action:'buy', listing_id: l.id, qty })
      .done(res => {
        const d = typeof res==='string'?JSON.parse(res):res;
        if (d.ok) {
          player = d.player;
          // ซื้อบางส่วน: ลด qty ใน cache — ซื้อหมด: ตัด listing ออก (backend ทำแบบเดียวกัน)
          window._mktListingsCache = (window._mktListingsCache||[]).map(x => {
            if (x.id != l.id) return x;
            const left = parseInt(x.qty) - qty;
            return left > 0 ? Object.assign({}, x, { qty: left }) : null;
          }).filter(Boolean);
          mktBuyStep = 3;
          _mktRefreshBody();
          renderItems();
          updateHUD();
          const g = document.getElementById('mkt2-gold');
          if (g) g.innerHTML = _icoHtml('💰') + ' ' + (player.gold||0).toLocaleString(); // innerHTML: เนื้อหาเป็นตัวเลขจากเกม — ปลอดภัย
        } else {
          alert(T('ไม่สามารถซื้อได้: ') + (d.error||'unknown'));
        }
      })
      .always(() => schedulePoll()); // chain เดียวเสมอ — ถ้ามี poll ค้างอยู่ .always ของ poll นั้นจะตั้งรอบถัดไปเอง
  }

  function _mktCancel(lid) {
    if (!confirm(T('ยกเลิกรายการนี้?'))) return;
    // หยุด poll ชั่วคราวป้องกัน race condition
    clearTimeout(pollTimer);
    $.post(baseUrl + 'xhrpg_market.php', { line_uid: player.line_uid, action:'cancel', listing_id: lid })
      .done(res => {
        const d = typeof res==='string'?JSON.parse(res):res;
        if (d.ok) {
          player = d.player;
          window._mktMyCache = (window._mktMyCache||[]).filter(l => l.id != lid);
          _mktRefreshBody();
          _mktUpdateMyBadge();
          renderItems();
          updateHUD();
        } else {
          alert(d.error||T('ไม่สามารถยกเลิกได้'));
        }
      })
      .always(() => schedulePoll()); // chain เดียวเสมอ — ถ้ามี poll ค้างอยู่ .always ของ poll นั้นจะตั้งรอบถัดไปเอง
  }

  // ── HISTORY ──────────────────────────────────────────────────────
  const HIST_STATUS_LABEL = { sold:'ขายได้', bought:'ซื้อมา', cancelled:'ยกเลิก', expired:'หมดอายุ', listed:'ลงขาย' };
  const HIST_STATUS_CLS   = { sold:'mkt-hb-sell', bought:'mkt-hb-buy', cancelled:'mkt-hb-cancel', expired:'mkt-hb-exp', listed:'mkt-hb-exp' };

  function _mktHistoryBody() {
    const chips = ['all','sold','bought','cancelled'].map(f => {
      const label = T(f==='all'?'ทั้งหมด':HIST_STATUS_LABEL[f]);
      return `<span class="mkt-hchip${mktHistFilter===f?' on':''}" onclick="xhrpg._mktSetHistFilter('${f}')">${label}</span>`;
    }).join('');
    return `<div class="mkt-hfilter">${chips}</div>
      <div id="mkt-hist-list"><div class="mkt-hload">${T('กำลังโหลด...')}</div></div>
      <div id="mkt-hist-sum" class="mkt-hsum"></div>`;
  }

  function _mktRenderHistList(rows, summary) {
    const el = document.getElementById('mkt-hist-list');
    const su = document.getElementById('mkt-hist-sum');
    if (!el) return;
    if (!rows.length) {
      el.innerHTML = '<div class="mkt-hload">' + T('ยังไม่มีประวัติ') + '</div>';
      if (su) su.innerHTML = '';
      return;
    }
    let lastDay = '';
    const html = rows.map(r => {
      const ts = parseInt(r.created_at) * 1000;
      const d  = new Date(ts);
      const dayStr = d.toLocaleDateString('th-TH', {day:'numeric',month:'short'});
      let dayHdr = '';
      if (dayStr !== lastDay) { dayHdr = `<div class="mkt-hday">${dayStr}</div>`; lastDay = dayStr; }
      const timeStr = d.toLocaleTimeString('th-TH', {hour:'2-digit',minute:'2-digit'});
      const gc = parseInt(r.gold_change);
      const gcHtml = gc > 0
        ? `<span class="mkt-hgc plus">+${gc.toLocaleString()} G</span>`
        : gc < 0
        ? `<span class="mkt-hgc minus">${gc.toLocaleString()} G</span>`
        : `<span class="mkt-hgc neu">−</span>`;
      const cpLine = r.counterpart_name
        ? (r.status==='sold' ? `← ${r.counterpart_name}` : `→ ${r.counterpart_name}`)
        : '';
      return `${dayHdr}<div class="mkt-hrow">
        <div class="mkt-hico">${_icoHtml(r.item_icon, 16)}</div>
        <div class="mkt-hmid">
          <div class="mkt-hname">${_mktTName(r.item_name)}</div>
          <div class="mkt-hmeta"><span class="mkt-hbadge ${HIST_STATUS_CLS[r.status]||''}">${HIST_STATUS_LABEL[r.status]?T(HIST_STATUS_LABEL[r.status]):r.status}</span>${cpLine ? ' · ' + cpLine : ''} · ${timeStr}</div>
        </div>
        <div class="mkt-hright">${gcHtml}<div class="mkt-hqty">×${r.qty}</div></div>
      </div>`;
    }).join('');
    el.innerHTML = _resIco(html);
    if (su && summary) {
      const inc = parseInt(summary.income)||0;
      su.innerHTML = `<span>${T('7 วันที่ผ่านมา · ขาย {a} รายการ · ซื้อ {b} รายการ', {a: summary.sold_count||0, b: summary.bought_count||0})}</span>
        <span class="${inc>=0?'mkt-hgc plus':'mkt-hgc minus'}">${inc>=0?'+':''}${inc.toLocaleString()} G</span>`;
    }
  }

  function _mktSetHistFilter(f) {
    mktHistFilter = f;
    window._mktHistCache = null;
    document.querySelectorAll('.mkt-hchip').forEach(c => c.classList.toggle('on', c.textContent === T(f==='all'?'ทั้งหมด':HIST_STATUS_LABEL[f])));
    const el = document.getElementById('mkt-hist-list');
    if (el) el.innerHTML = '<div class="mkt-hload">' + T('กำลังโหลด...') + '</div>';
    $.post(baseUrl + 'xhrpg_market.php', { line_uid: player?.line_uid, action:'get_history', filter: f })
      .done(res => {
        const d = typeof res==='string'?JSON.parse(res):res;
        if (d.ok) { window._mktHistCache = d; _mktRenderHistList(d.rows, d.summary); }
      });
  }

  function _mktBindEvents() {
    // แท็บซื้อ: โหลด listings เมื่อ cache ว่าง (กริดโชว์ "กำลังโหลด..." อยู่แล้ว)
    if (mktMode === 'buy' && !mktSellOpen && window._mktListingsCache == null) {
      $.post(baseUrl + 'xhrpg_market.php', { line_uid: player?.line_uid, action:'get_listings' })
        .done(res => {
          const d = typeof res==='string'?JSON.parse(res):res;
          if (d.ok) {
            window._mktListingsCache = d.listings;
            if (mktMode === 'buy' && !mktSellOpen) _mktRefreshBody();
          }
        });
    }
    if (mktMode === 'history') {
      if (!window._mktHistCache) {
        $.post(baseUrl + 'xhrpg_market.php', { line_uid: player?.line_uid, action:'get_history', filter: mktHistFilter })
          .done(res => {
            const d = typeof res==='string'?JSON.parse(res):res;
            if (d.ok) { window._mktHistCache = d; _mktRenderHistList(d.rows, d.summary); }
          });
      } else {
        _mktRenderHistList(window._mktHistCache.rows, window._mktHistCache.summary);
      }
    }
    // โหลด my listings เมื่อ cache ว่าง — ใช้ทั้งแท็บของฉันและ badge บนแท็บ
    if (window._mktMyCache == null) {
      $.post(baseUrl + 'xhrpg_market.php', { line_uid: player?.line_uid, action:'get_my_listings' })
        .done(res => {
          const d = typeof res==='string'?JSON.parse(res):res;
          if (d.ok) {
            window._mktMyCache = d.listings;
            _mktUpdateMyBadge();
            if (mktMode === 'my' && !mktSellOpen) _mktRefreshBody();
          }
        });
    } else {
      _mktUpdateMyBadge();
    }
  }

