  let guideChap = 0;
  let guideOpen = null;

  function renderGuide() {
    const root = document.getElementById('guide-root');
    if (!root) return;
    root.innerHTML = _guideBuild();
  }

  function _guideBuild() {
    const chapList = GUIDE_CHAPTERS.map((c, i) =>
      `<div class="gd-chap ${guideChap===i?'on':''}" onclick="xhrpg._guideSetChap(${i})">
        <span class="gd-chap-ico">${c.icon}</span>
        <span class="gd-chap-lbl">${T(c.title)}</span>
        <span class="gd-chap-arr">${guideChap===i?'▾':'›'}</span>
      </div>
      ${guideChap===i ? _guideItems(i) : ''}`
    ).join('');
    return `<div class="gd-root">${chapList}</div>`;
  }

  function _guideItems(ci) {
    const items = GUIDE_CHAPTERS[ci].items;
    return `<div class="gd-items">${items.map((it, ii) => `
      <div class="gd-item ${guideOpen===ci+','+ii?'open':''}" onclick="xhrpg._guideToggle(${ci},${ii})">
        <div class="gd-q"><span class="gd-arrow">${guideOpen===ci+','+ii?'▾':'›'}</span>${T(it.q)}</div>
        ${guideOpen===ci+','+ii ? `<div class="gd-a">${T(it.a)}</div>` : ''}
      </div>`).join('')}</div>`;
  }

  function _guideSetChap(i) {
    guideChap = i; guideOpen = null;
    const root = document.getElementById('guide-root');
    if (root) root.innerHTML = _guideBuild();
  }

  function _guideToggle(ci, ii) {
    const key = ci+','+ii;
    guideOpen = guideOpen === key ? null : key;
    const root = document.getElementById('guide-root');
    if (root) root.innerHTML = _guideBuild();
  }

